package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx

/** Scalar reference geometry for ordinary and FLOW query tails. */
data class PathFact(val base: AccessPathBase, val path: List<AccessorIdx>, val tail: Tail, val mark: MarkSlot)
data class Pattern(val fact: PathFact, val exclusion: ExclusionSet)

data class Conclusion(val fact: PathFact, val exclusion: ExclusionSet, val demand: Boolean) {
    init {
        check(fact.tail != Tail.ANY || demand) { "W6: a may conclusion must be DEMAND" }
        check(exclusion == ExclusionSet.Empty || fact.tail == Tail.STAR || fact.tail == Tail.ANY_TAINT ||
            (fact.tail == Tail.EXACT && fact.mark is MarkSlot.Star)) {
            "Only a STAR or must conclusion can exclude fields"
        }
    }
}


fun <T> List<T>.startsWith(p: List<T>): Boolean = size >= p.size && subList(0, p.size) == p

val STATIC: AccessPathBase = AccessPathBase.ClassStatic



data class DemandPattern(val entry: Pattern, val exit: Pattern?)

fun tailAdmits(tail: Tail, exclusion: ExclusionSet, r: List<AccessorIdx>): Boolean = when (tail) {
    Tail.STAR, Tail.ANY_TAINT -> exclusion.admits(r)   // r = [] or the first accessor of r is not excluded
    Tail.ANY -> true
    Tail.EXACT -> r.isEmpty()
}
fun Pattern.tailAdmits(r: List<AccessorIdx>) = tailAdmits(fact.tail, exclusion, r)

fun markSub(i: MarkSlot, c: MarkSlot, catalog: MarkTable? = null): Boolean = when (i) {
    is MarkSlot.Star -> when (c) {
        is MarkSlot.Star -> i.excluded.isSubsetOf(c.excluded)   // *∖X ⊇ *∖Y if and only if X ⊆ Y; * ⊇ every abstract mark
        is MarkSlot.Concrete -> c.mark !in i.excluded
    }
    is MarkSlot.Concrete -> c is MarkSlot.Concrete && (catalog?.coversAtom(i.mark, c.mark) ?: (c.mark == i.mark))
}

private fun tailSub(i: Pattern, c: Pattern): Boolean = when (i.fact.tail) {
    Tail.ANY -> true
    Tail.EXACT -> c.fact.tail == Tail.EXACT
    Tail.STAR, Tail.ANY_TAINT -> when (c.fact.tail) {       // the exclusion of i must exclude only what c excludes
        Tail.EXACT -> true
        Tail.ANY -> i.exclusion == ExclusionSet.Empty
        Tail.STAR, Tail.ANY_TAINT -> i.exclusion.isSubsetOf(c.exclusion)
    }
}

fun covers(i: Pattern, c: Pattern, catalog: MarkTable? = null): Boolean {
    if (i.fact.base != c.fact.base || !markSub(i.fact.mark, c.fact.mark, catalog)) return false
    val p = i.fact.path
    val q = c.fact.path
    if (!q.startsWith(p)) return false
    return if (q.size == p.size) tailSub(i, c) else i.tailAdmits(q.drop(p.size))
}

fun overlap(a: Pattern, b: Pattern): Boolean {
    if (a.fact.base != b.fact.base) return false
    val p = a.fact.path
    val q = b.fact.path
    return when {
        q.startsWith(p) -> a.tailAdmits(q.drop(p.size))
        p.startsWith(q) -> b.tailAdmits(p.drop(q.size))
        else -> false
    }
}

fun applicable(j: Pattern, a: Pattern, catalog: MarkTable? = null): Boolean =
    covers(j, a, catalog) && (!j.fact.tail.isAny || a.fact.tail.isAny)

fun inside(j: Pattern, a: Pattern, catalog: MarkTable? = null): Boolean =
    covers(a.copy(fact = a.fact.copy(mark = MarkSlot.Star(MarkSet.EMPTY))), j, catalog) && markSub(j.fact.mark, a.fact.mark, catalog)

/** Transient native-record read. Never emitted, started, interned as an InitialAp, or persisted. */
data class RecordLeafView(val premise: Pattern, val result: Conclusion)

fun summaryEdge(j: Pattern, g: Conclusion): PathEdge {
    val jOwn = j.fact.tail == Tail.ANY_TAINT
    val gOwn = g.fact.tail == Tail.ANY_TAINT
    return PathEdge(j.fact, g.fact,
        (if (jOwn) ExclusionSet.Empty else j.exclusion).union(if (gOwn) ExclusionSet.Empty else g.exclusion),
        fromExclusion = if (jOwn) j.exclusion else ExclusionSet.Empty,
        toExclusion = if (gOwn) g.exclusion else ExclusionSet.Empty)
}

/** Concrete native must views retain their existing policy. New FLOW must views always return an ANY demand. */
private fun mustRecordReadView(p: Pattern, g: Conclusion): RecordLeafView? {
    if (!g.demand && p.fact.mark is MarkSlot.Star && g.fact.mark is MarkSlot.Star &&
        ((p.fact.tail == Tail.ANY_TAINT && g.fact.tail in setOf(Tail.STAR, Tail.ANY_TAINT)) ||
            (p.fact.tail == Tail.STAR && g.fact.tail == Tail.ANY_TAINT))) {
        return RecordLeafView(Pattern(g.fact.copy(tail = Tail.STAR, mark = p.fact.mark), g.exclusion),
            Conclusion(p.fact.copy(tail = Tail.ANY, mark = g.fact.mark), ExclusionSet.Empty, demand = true))
    }
    val concrete = p.fact.mark is MarkSlot.Concrete && g.fact.mark is MarkSlot.Concrete
    val accepted = !g.demand && concrete && when (p.fact.tail) {
        Tail.EXACT -> p.exclusion == ExclusionSet.Empty && g.fact.tail == Tail.ANY_TAINT
        Tail.ANY_TAINT -> g.fact.tail == Tail.ANY_TAINT ||
            (g.fact.tail == Tail.EXACT && g.exclusion == ExclusionSet.Empty)
        else -> false
    }
    if (!accepted) return null
    val readPremise = if (g.fact.tail == Tail.ANY_TAINT)
        Pattern(g.fact.copy(tail = Tail.STAR), g.exclusion)          // retain the old conclusion E and concrete mark
    else Pattern(g.fact, ExclusionSet.Empty)                        // exact conclusion stays exact
    val demand = p.fact.tail == Tail.ANY_TAINT
    val resultFact = if (demand) p.fact.copy(tail = Tail.ANY) else p.fact
    return RecordLeafView(readPremise, Conclusion(resultFact, ExclusionSet.Empty, demand))   // forget old must-input E
}

/** Raw normal singleton record only. CurrentSimplifications.MustViews.readView_factored_equiv checks the accepted
 *  must constructor. Retain generic micro-edge revEdge and its fallback guards for every other native shape. */
fun reverseRecordLeaf(direction: Direction, p: Pattern, g: Conclusion): RecordLeafView? {
    if (g.demand) return null
    if (p.exclusion != ExclusionSet.Empty && p.fact.tail != Tail.STAR && p.fact.tail != Tail.ANY_TAINT) return null
    if (direction == Direction.BACKWARD && (p.fact.tail == Tail.ANY_TAINT || g.fact.tail == Tail.ANY_TAINT)) return null
    if (direction == Direction.FORWARD) mustRecordReadView(p, g)?.let { return it }
    if (p.fact.tail == Tail.ANY_TAINT) return null                   // no unsupported native must-input fallback
    if (p.fact.tail == Tail.STAR && p.fact.mark is MarkSlot.Concrete) return null   // invalid native normal shape
    val rev = revEdge(summaryEdge(p, g)) ?: return null
    return RecordLeafView(Pattern(rev.from, ExclusionSet.Empty),
        Conclusion(rev.to, rev.exclusion, demand = rev.to.tail == Tail.ANY))
}

/** Identity classification without starting a transient premise. Concrete STAR readers are effects. */
fun recordLeafIdentity(v: RecordLeafView): Boolean = !v.result.demand && v.premise.fact.base != AccessPathBase.Zero &&
    (v.premise.fact.tail == Tail.EXACT || (v.premise.fact.tail == Tail.STAR && v.premise.fact.mark is MarkSlot.Star)) &&
    v.result.fact == v.premise.fact && v.result.exclusion == v.premise.exclusion


fun meet(a: Pattern, d: Pattern): Pair<Tail, ExclusionSet> {
    return when {
        a.fact.tail == Tail.ANY_TAINT && d.fact.tail == Tail.STAR ->
            Tail.ANY_TAINT to a.exclusion.union(d.exclusion)
        a.fact.tail.isAny && d.fact.tail.isAny -> a.fact.tail to a.exclusion
        a.fact.tail.isAny -> d.fact.tail to d.exclusion
        d.fact.tail.isAny -> a.fact.tail to a.exclusion
        a.fact.tail == Tail.EXACT || d.fact.tail == Tail.EXACT -> Tail.EXACT to ExclusionSet.Empty
        else -> Tail.STAR to a.exclusion.union(d.exclusion)
    }
}

/** Demand-only widening. Actual facts, native records and concrete demand retain field E. */
fun normalizeDemandFieldExclusion(pattern: Pattern): Pattern =
    if (pattern.fact.mark is MarkSlot.Star && pattern.fact.tail == Tail.STAR &&
        pattern.exclusion != ExclusionSet.Empty) pattern.copy(exclusion = ExclusionSet.Empty)
    else pattern

/** Scalar table view, including forward uniform templates. The engine passes its run policy explicitly. */
fun emit(d: Pattern, a: Pattern, catalog: MarkTable? = null): Pattern? =
    RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = catalog).emit(d, a)

fun flowForm(d: Pattern): Pattern {
    val star = MarkSlot.Star(MarkSet.EMPTY)
    return if (d.fact.tail == Tail.ANY) Pattern(d.fact.copy(tail = Tail.STAR, mark = star), ExclusionSet.Empty)
    else Pattern(d.fact.copy(mark = star), d.exclusion)                // `STAR/E` keeps E
}

fun commonPart(d: Pattern, a: Pattern, catalog: MarkTable? = null): Pattern? {
    if (d.fact.base != a.fact.base) return null
    // a T demand needs the mark T: an abstract `a` gives nothing ("the added fact can't satisfy the demand", F72);
    // `*` admits every mark (Lean: markMatchB; with no `*∖X` pattern it is markSub)
    if (!markSub(d.fact.mark, a.fact.mark, catalog)) return null
    val p = d.fact.path
    val q = a.fact.path
    return when {
        q.size > p.size && q.startsWith(p) ->                                   // below: the fact itself
            if (d.tailAdmits(q.drop(p.size))) a else null
        q == p -> {                                                              // at: the meet of the tails
            val (tail, excl) = meet(a, d)
            Pattern(a.fact.copy(tail = tail), excl)
        }
        p.startsWith(q) ->                                    // above: the demand chain, the meet of the tails
            if (a.tailAdmits(p.drop(q.size))) {
                // E excludes first accessors at q. After the admitted descent to p it has no effect there.
                // Keep the demand's own E at p, including the MUST/STAR and correlated STAR cells.
                val (tail, excl) = meet(a.copy(exclusion = ExclusionSet.Empty), d)
                Pattern(d.fact.copy(tail = tail, mark = a.fact.mark), excl)
            } else null
        else -> null
    }
}

fun satisfies(j: Pattern, a: Pattern, restricted: Boolean): Boolean {
    if (j.fact.tail == Tail.ANY_TAINT && j.fact.mark is MarkSlot.Star)
        return a.fact.tail == Tail.ANY_TAINT && markSub(j.fact.mark, a.fact.mark) &&
            covers(a.copy(fact = a.fact.copy(mark = MarkSlot.STAR)), j.copy(fact = j.fact.copy(mark = MarkSlot.STAR)))
    return if (!restricted) applicable(j, a) || inside(j, a)
    else if (j.fact.tail == Tail.STAR && j.exclusion == ExclusionSet.Empty && j.fact.mark == MarkSlot.STAR)
        overlap(j, a)
    else inside(j, a) || ((j.fact.mark == MarkSlot.STAR || j.fact.tail == Tail.STAR) && applicable(j, a))
}

fun recordDemand(j: Pattern, a: Pattern, resultDemand: Boolean): Boolean =
    resultDemand || (j.fact.tail == Tail.ANY_TAINT && !inside(j, a))
fun insideLoc(j: Pattern, d: Pattern): Boolean {
    val star = MarkSlot.Star(MarkSet.EMPTY)
    return covers(d.copy(fact = d.fact.copy(mark = star)), j.copy(fact = j.fact.copy(mark = star)))
}

fun insideDemand(j: Pattern, d: Pattern, catalog: MarkTable? = null): Boolean {
    val entry = normalizeDemandFieldExclusion(d)
    return insideLoc(j, entry) && markSub(entry.fact.mark, j.fact.mark, catalog)
}

fun marksMeet(dp: MarkSlot, c: MarkSlot, catalog: MarkTable? = null): Boolean = when {
    dp is MarkSlot.Concrete && c is MarkSlot.Concrete -> (catalog?.let { it.coversAtom(dp.mark, c.mark) || it.coversAtom(c.mark, dp.mark) } ?: (dp.mark == c.mark))
    dp is MarkSlot.Concrete -> dp.mark !in (c as MarkSlot.Star).excluded      // an abstract conclusion stays as it is
    c is MarkSlot.Concrete -> c.mark !in (dp as MarkSlot.Star).excluded
    else -> true
}

fun meetConclusion(sc: Conclusion, dp: Pattern): Conclusion = when {
    !sc.fact.tail.isAny -> sc                                     // `$`; `*` stays whole (a FLOW conclusion, F72)
    dp.fact.tail == Tail.EXACT -> sc.copy(fact = sc.fact.copy(tail = Tail.EXACT),
        exclusion = if (sc.fact.mark is MarkSlot.Star && sc.fact.tail == Tail.ANY_TAINT) sc.exclusion else ExclusionSet.Empty)
    sc.fact.tail == Tail.ANY_TAINT && dp.fact.tail == Tail.STAR -> sc.copy(exclusion = sc.exclusion.union(dp.exclusion))
    else -> sc                                                    // `[any] ∩ STAR/E2` (the exception), `∩ [any]`
}

fun restrict(sp: Pattern, sc: Conclusion, d: DemandPattern, catalog: MarkTable? = null,
             policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = catalog)): Conclusion? {
    if (!policy.canStoreInitial(d.entry, sp)) return null
    return restrictConclusionOnly(sc, d.exit, catalog)
}

fun restrictConclusionOnly(sc: Conclusion, exit: Pattern?, catalog: MarkTable? = null): Conclusion? {
    val dp = normalizeDemandFieldExclusion(exit ?: return null)
    if (!marksMeet(dp.fact.mark, sc.fact.mark, catalog)) return null  // the mark of the conclusion meets the mark of D-p
    if (sc.fact.base != dp.fact.base) return null
    val p = dp.fact.path
    val q = sc.fact.path
    return when {
        q == p -> meetConclusion(sc, dp)                                         // at D-p: the meet
        q.startsWith(p) -> if (dp.tailAdmits(q.drop(p.size))) sc else null     // below D-p: keeps E
        p.startsWith(q) -> when (sc.fact.tail) {                                // above D-p
            Tail.ANY, Tail.ANY_TAINT ->
                if (!sc.exclusion.admits(p.drop(q.size))) null                   // E of `[any-taint]/E` (W8)
                else if (dp.fact.tail == Tail.EXACT)                             // the chain of D-p, the layer stays
                    sc.copy(fact = sc.fact.copy(path = p, tail = Tail.EXACT), exclusion = ExclusionSet.Empty)
                else sc.copy(fact = sc.fact.copy(path = p),
                    exclusion = if (sc.fact.tail == Tail.ANY_TAINT && dp.fact.tail == Tail.STAR) dp.exclusion
                                else ExclusionSet.Empty)                         // [any-taint]/E2 under STAR/E2 (W8)
            Tail.STAR -> if (sc.exclusion.admits(p.drop(q.size))) sc else null   // a FLOW conclusion (F72)
            else -> null                                                         // `$`: no common location
        }
        else -> null
    }
}

data class PathEdge(val from: PathFact, val to: PathFact, val exclusion: ExclusionSet,
                    val fromExclusion: ExclusionSet = ExclusionSet.Empty,     // Ej of a must-premise (a summary, a record)
                    val toExclusion: ExclusionSet = ExclusionSet.Empty) {     // Et of an `[any-taint]/Et` summary conclusion
    @Volatile internal var compiled: CompiledEdge? = null
}

private fun PathEdge.premiseAdmits(r: List<AccessorIdx>): Boolean = when (from.tail) {
    Tail.EXACT -> r.isEmpty()
    Tail.ANY_TAINT -> fromExclusion.admits(r)   // a must-premise: Ej
    else -> exclusion.admits(r)        // `*`: E; `[any]`: E is Empty unless the target is `*` (row 1)
}

private class Shape(val path: List<AccessorIdx>, val tail: Tail, val exclusion: ExclusionSet, val demand: Boolean)

private fun below(c: Conclusion, edge: PathEdge, r: List<AccessorIdx>): Shape? {
    if (!edge.premiseAdmits(r)) return null
    val to = edge.to
    if (to.tail == Tail.STAR && r.isNotEmpty() && !edge.exclusion.admits(r)) return null
    return when (to.tail) {
        Tail.STAR -> when {
            r.isNotEmpty() -> Shape(to.path + r, c.fact.tail, c.exclusion, demand = false)   // keeps Ec (W8)
            c.fact.tail == Tail.EXACT -> Shape(to.path, Tail.EXACT,
                if (c.fact.mark is MarkSlot.Star) c.exclusion.union(edge.exclusion) else ExclusionSet.Empty, false)
            c.fact.tail == Tail.ANY -> Shape(to.path, Tail.ANY, ExclusionSet.Empty, demand = true)   // W6
            else -> Shape(to.path, c.fact.tail, c.exclusion.union(edge.exclusion), false)  // `STAR/Ec`, or the exclusion
        }                                                                                 // edge on `[any-taint]/Ec` (W8)
        Tail.ANY -> Shape(to.path, Tail.ANY, ExclusionSet.Empty, demand = true)               // W6: a may
        Tail.ANY_TAINT, Tail.EXACT -> Shape(to.path, to.tail,                                  // a must, or `$`
            if (to.tail == Tail.ANY_TAINT) edge.toExclusion else ExclusionSet.Empty,           // Et (W8)
            demand = false)        // W2 and the concrete premise gate reject STAR input; geometry still precedes that gate
    }
}

private fun PathEdge.isExcludedIdentityKeep(): Boolean =
    from.base == to.base && from.path == to.path && from.tail == Tail.STAR &&
        to.tail == Tail.STAR && exclusion != ExclusionSet.Empty

private fun above(c: Conclusion, edge: PathEdge, r: List<AccessorIdx>): Shape? {
    val admitted = when (c.fact.tail) {
        Tail.STAR, Tail.ANY_TAINT -> c.exclusion.admits(r); Tail.ANY -> true; Tail.EXACT -> false
    }
    if (!admitted) {
        // An excluded identity keep is the existing field-write effect, not a read.
        if (c.fact.tail == Tail.EXACT && c.fact.mark is MarkSlot.Star && edge.isExcludedIdentityKeep() && c.exclusion.admits(r))
            return Shape(edge.to.path, Tail.ANY, ExclusionSet.Empty, demand = true)
        return null
    }
    val to = edge.to
    if (c.fact.tail != Tail.ANY_TAINT) {           // a `*` fact loses its correlation; an `[any]` fact is demand (W6)
        val tail = if (to.tail == Tail.EXACT) Tail.EXACT else Tail.ANY
        return Shape(to.path, tail, ExclusionSet.Empty, demand = true)
    }
    return when (to.tail) {                        // every admitted location of c carries its mark: nothing is lost
        Tail.EXACT -> Shape(to.path, Tail.EXACT,
            if (c.fact.mark is MarkSlot.Star && r.isEmpty()) c.exclusion else ExclusionSet.Empty, demand = false)
        Tail.ANY_TAINT -> Shape(to.path, Tail.ANY_TAINT, edge.toExclusion, demand = false)    // Et
        Tail.ANY -> Shape(to.path, Tail.ANY, ExclusionSet.Empty, demand = true)               // W6: a may
        Tail.STAR -> Shape(to.path, Tail.ANY_TAINT, edge.exclusion, demand = false)          // the edge exclusion (W8)
    }
}

sealed interface EdgeOutcome {
    data object None : EdgeOutcome
    data class Fact(val conclusion: Conclusion) : EdgeOutcome
    data class Request(val mark: TaintMark) : EdgeOutcome                  // run 1 only (§4.5)
    data class PositionRequest(val path: List<AccessorIdx>) : EdgeOutcome     // run 1 only (§4.10 item 1)
}

fun rootOrClass(q: List<AccessorIdx>): Boolean = q.isEmpty() || (q.size == 1 && q[0].isClass())

fun concat(c: Conclusion, edge: PathEdge, edgeDemand: Boolean = false,
           staticIdentity: Boolean = false, restricted: Boolean = false, run1: Boolean = false): EdgeOutcome {
    val from = edge.from
    check(from.mark !is MarkSlot.Star || from.mark.excluded.isEmpty)          // S7
    check(edge.to.mark !is MarkSlot.Concrete || from.mark is MarkSlot.Concrete)          // S7
    check(from.tail != Tail.EXACT || edge.to.tail != Tail.STAR || from.mark is MarkSlot.Star)
    check(edge.to.tail != Tail.ANY_TAINT || edge.to.mark is MarkSlot.Concrete || from.mark is MarkSlot.Star)
    if (c.fact.base != from.base) return EdgeOutcome.None
    val p = from.path
    val q = c.fact.path
    val isAbove = p.size > q.size && p.startsWith(q)
    val shape = when {
        q.startsWith(p) -> below(c, edge, q.drop(p.size))
        isAbove -> above(c, edge, p.drop(q.size))
        else -> null
    } ?: return EdgeOutcome.None
    if (staticIdentity && from.base == STATIC && isAbove && rootOrClass(q)) {   // the static exception (§4.10)
        check(!restricted)
        return EdgeOutcome.PositionRequest(p.take(2))                          // cut to the static field or class
    }
    val premiseMark = from.mark
    if (premiseMark is MarkSlot.Concrete) {                                   // step 4: the mark gate
        when (val cm = c.fact.mark) {
            is MarkSlot.Concrete -> if (cm.mark != premiseMark.mark) return EdgeOutcome.None
            is MarkSlot.Star -> {
                if (premiseMark.mark in cm.excluded) return EdgeOutcome.None
                if (restricted) return EdgeOutcome.None                       // F72: no request after run 1 (§4.5)
                return EdgeOutcome.Request(premiseMark.mark)
            }
        }
    }
    val mark = compose(edge.to.mark, c.fact.mark) ?: return EdgeOutcome.None  // step 5
    val cover = run1 && shape.exclusion != ExclusionSet.Empty
    return EdgeOutcome.Fact(normalize(PathFact(edge.to.base, shape.path, shape.tail, mark),
        if (cover) ExclusionSet.Empty else shape.exclusion, c.demand || edgeDemand || shape.demand || cover))
}

fun compose(to: MarkSlot, c: MarkSlot): MarkSlot? = when (to) {
    is MarkSlot.Concrete -> to
    is MarkSlot.Star -> when (c) {
        is MarkSlot.Star -> MarkSlot.Star(to.excluded + c.excluded)
        is MarkSlot.Concrete -> if (c.mark in to.excluded) null else c
    }
}

fun normalize(f: PathFact, exclusion: ExclusionSet, demand: Boolean): Conclusion = when {
    demand && f.mark is MarkSlot.Star && (f.tail == Tail.EXACT || f.tail == Tail.ANY_TAINT) ->
        Conclusion(f.copy(tail = Tail.ANY), ExclusionSet.Empty, demand = true)
    f.tail == Tail.ANY -> Conclusion(f, ExclusionSet.Empty, demand = true)                                  // W6
    f.tail == Tail.ANY_TAINT -> {
        Conclusion(f, exclusion, demand)
    }
    else -> Conclusion(f, if (f.tail == Tail.EXACT && f.mark is MarkSlot.Concrete) ExclusionSet.Empty else exclusion, demand)
}

/** ap.md §6.5 (Lean startFact; a must-premise: AnyTaint.startT, with the exclusion AnyTaintEx.startX). No direction
 *  parameter: a must-premise occurs only in a forward restricted run (A1), and no other row reads the run. */
fun startFact(i: Pattern): Conclusion = when (i.fact.tail) {
    Tail.STAR -> Conclusion(i.fact, i.exclusion, demand = i.fact.mark is MarkSlot.Concrete)
    Tail.ANY -> Conclusion(i.fact, ExclusionSet.Empty, demand = true)
    Tail.ANY_TAINT -> Conclusion(i.fact, i.exclusion, demand = false)                // a must-premise: itself, normal
    Tail.EXACT -> Conclusion(i.fact, ExclusionSet.Empty, demand = false)
}

/** ap.md §4.4 (Lean cutPath, limitF; with the exclusion AnyTaintEx.limitFX). An `[any-taint]/E` fact over the limit
 *  becomes `[any]` in the demand layer and loses E (W8, A2). */
fun limit(c: Conclusion, fieldLimit: Int): Conclusion {
    require(fieldLimit >= 1) { "The field limit must be positive" }
    var n = 0
    for ((k, a) in c.fact.path.withIndex())
        if (a.isCounted() && ++n > fieldLimit)
            return Conclusion(c.fact.copy(path = c.fact.path.take(k), tail = Tail.ANY), ExclusionSet.Empty, demand = true)
    return c
}

enum class Pos { INSIDE, DISJOINT, PART }

/** ap.md §4.7 (Lean cleanPos; with the exclusion AnyTaintEx.cleanPosX: a cleaner strictly below an `[any-taint]/E` fact
 *  through an accessor in E is `disjoint`). The tree form is cleanPosAt (Part I §5.6). */
fun cleanPos(cl: Cleaner, c: PathFact, exclusion: ExclusionSet): Pos {
    if (c.base != cl.base) return Pos.DISJOINT
    val p = cl.path?.toList().orEmpty()
    val q = c.path
    return when {
        q.size > p.size && q.startsWith(p) -> if (cl.reach == CleanReach.EXACT) Pos.DISJOINT else Pos.INSIDE
        q == p -> when {
            cl.reach == CleanReach.AT_AND_BELOW -> Pos.INSIDE
            c.tail == Tail.EXACT -> if (cl.reach == CleanReach.EXACT) Pos.INSIDE else Pos.DISJOINT
            else -> Pos.PART
        }
        p.startsWith(q) -> when (c.tail) {
            Tail.EXACT -> Pos.DISJOINT
            Tail.STAR, Tail.ANY, Tail.ANY_TAINT ->                                  // `[any]`: the Empty exclusion admits
                if (exclusion.admits(p.drop(q.size))) Pos.PART else Pos.DISJOINT
        }
        else -> Pos.DISJOINT
    }
}

class CleanOut(val facts: List<Conclusion>, val request: TaintMark?)

/** ap.md §4.7, F75 selected-mark split (BaseCleaner.cleanRes); concrete/all-marks rows keep concPart. */
fun cleanRes(cl: Cleaner, c: Conclusion, run1: Boolean = false): CleanOut {
    val raw = if (run1 && c.fact.base == STATIC && cl.base == STATIC &&
        c.fact.mark is MarkSlot.Star && cl.mark != null && cleanPos(cl, c.fact, c.exclusion) == Pos.DISJOINT)
        CleanOut(listOf(c), null) else cleanResRaw(cl, c)
    return if (!run1) raw else CleanOut(raw.facts.map { value ->
        if (value.exclusion == ExclusionSet.Empty) value
        else value.copy(exclusion = ExclusionSet.Empty, demand = true)
    }, raw.request)
}

private fun cleanResRaw(cl: Cleaner, c: Conclusion): CleanOut {
    if (c.fact.base != cl.base) return CleanOut(listOf(c), null)
    val abstractMark = c.fact.mark as? MarkSlot.Star
    val selected = cl.mark
    if (abstractMark != null && selected != null)
        return CleanOut(listOf(c.copy(fact = c.fact.copy(mark = MarkSlot.Star(abstractMark.excluded + selected)))), selected)
        // The caller records this request only in run 1. Do not test the path or T ∈ X first.
    if (abstractMark != null && selected == null) {
        return CleanOut(wholeFlowClean(cl, c), null)
    }
    val pos = cleanPos(cl, c.fact, c.exclusion)
    if (pos == Pos.DISJOINT) return CleanOut(listOf(c), null)
    return when (val mk = c.fact.mark) {
        is MarkSlot.Concrete ->
            if (cl.mark != null && cl.mark != mk.mark) CleanOut(listOf(c), null)                  // T' not cleaned
            else if (pos == Pos.INSIDE) CleanOut(emptyList(), null)
            else CleanOut(concPart(cl, c), null)                                                  // one or two facts (A2)
        is MarkSlot.Star -> {
            check(cl.mark == null)                                               // selected mark handled before cleanPos
            CleanOut(if (pos == Pos.INSIDE) emptyList() else listOf(normalize(c.fact, c.exclusion, demand = true)), null)
        }
    }
}

/** Whole-position FLOW kill. Retain one uncertain inner residual, which covers deeper ones. */
internal fun wholeFlowClean(cl: Cleaner, c: Conclusion): List<Conclusion> {
    val path = cl.path?.toList().orEmpty()
    val q = c.fact.path
    if (q.startsWith(path)) return emptyList()
    if (!path.startsWith(q) || !c.exclusion.admits(path.drop(q.size))) return listOf(c)
    if (c.fact.tail == Tail.ANY) return listOf(c)
    val result = ArrayList<Conclusion>()
    result += c.copy(exclusion = c.exclusion.union(ExclusionSet.of(path[q.size])))
    if (q.size + 1 < path.size) {
        if (c.fact.tail == Tail.ANY_TAINT) {
            for (depth in q.size + 1 until path.size)
                result += c.copy(fact = c.fact.copy(path = path.take(depth)), exclusion = ExclusionSet.of(path[depth]))
        } else result += c.copy(fact = c.fact.copy(path = path.take(q.size + 1), tail = Tail.ANY),
            exclusion = ExclusionSet.Empty, demand = true)
    }
    return result
}

/** ap.md §4.7 (Lean concPart; with the exclusion AnyTaintEx.partX): a normal `[any-taint]/E` fact at x.p and a cleaner ONE
 *  accessor below it, at x.p.f: `atAndBelow` gives the fact with `E ∪ {f}`, `below` gives it and `(x, p.f, $, T)`, in
 *  the layer of c (A2). An any-tail fact at x.p under a `below` cleaner AT x.p keeps `(x, p, $, T)` in its layer. Any
 *  other `part` result (the `exact` cleaner one accessor below too) goes to the demand layer: an `[any-taint]` fact as
 *  `[any]`, with no exclusion (W8). */
fun concPart(cl: Cleaner, c: Conclusion): List<Conclusion> {
    val p = cl.path?.toList().orEmpty()
    val q = c.fact.path
    if (c.fact.tail == Tail.ANY_TAINT && p.size == q.size + 1 && p.startsWith(q) && cl.reach != CleanReach.EXACT) {
        val kept = c.copy(exclusion = c.exclusion.union(ExclusionSet.of(p.last())))          // `[any-taint]/(E ∪ {f})`
        return if (cl.reach == CleanReach.AT_AND_BELOW) listOf(kept)
               else listOf(kept, c.copy(fact = c.fact.copy(path = p, tail = Tail.EXACT), exclusion = ExclusionSet.Empty))   // + x.p.f.$
    }
    return listOf(
        if ((c.fact.tail.isAny || c.fact.tail == Tail.STAR) && cl.reach == CleanReach.BELOW && q == p)
            c.copy(fact = c.fact.copy(tail = Tail.EXACT), exclusion = ExclusionSet.Empty)   // in the layer of c
        else c.copy(demand = true))
}

sealed interface CheckResult { data object None : CheckResult; data object Holds : CheckResult; data class Request(val mark: TaintMark) : CheckResult }

/** ap.md §4.9 and §4.6 (Lean `check`, `ND.DN.conj`; renamed: `check` is the Kotlin assert): the check of one mark literal `s`
 *  on one fact. The tree form is ApOps.checkMark (Part I §5.8). The §11.2 difference: the effective-mark case is asserted away. */
fun markCheck(i: Pattern, f: Conclusion, s: Pattern, restricted: Boolean = false): CheckResult {
    val t = (s.fact.mark as MarkSlot.Concrete).mark
    if (!overlap(Pattern(f.fact, f.exclusion), s)) return CheckResult.None
    return when (val mk = f.fact.mark) {
        is MarkSlot.Concrete -> if (mk.mark == t) CheckResult.Holds else CheckResult.None
        is MarkSlot.Star -> if (restricted || t in mk.excluded) CheckResult.None
                            else { check(i.fact.mark is MarkSlot.Star); CheckResult.Request(t) }
    }
}

/** ap.md §4.6 (Lean ND.conjLayer; with the `[any-taint]` rule AnyTaintND.conjLayerT): the layer of one input of a literal
 *  that holds on it. Demand if the input is in the demand layer, or if the literal does not cover it and it is not
 *  `[any-taint]` (a normal `[any-taint]` input that overlaps its literal and passes its mark gate keeps the result
 *  normal: every location of it carries the mark, AnyTaintND.lit_loc). The overlap of `markCheck` reads the exclusion of
 *  an `[any-taint]/E` input (A2), so an input in the excluded part never reaches here.
 *  For the legal matched TAINT literal shapes, CurrentProposal.LiteralLayer proves this equals f.demand. */
fun conjDemand(f: Conclusion, lit: Pattern): Boolean =
    f.demand || (!covers(lit, Pattern(f.fact, f.exclusion)) && f.fact.tail != Tail.ANY_TAINT)

/** ap.md §4.5 chain answer (Lean answerInit) and §4.10 item 4 (Lean Statics.SCtx.ansInit). Precondition: a overlaps i, a.mark = t.
 *  Run 1 has no must-premise (W8 (c)): an `[any-taint]/E` `a` gives the static mark answer with the tail `[any]` and no
 *  exclusion (a larger premise, demand: sound). */
fun answer(i: Pattern, a: Pattern, t: TaintMark): Pattern = when {
    i.fact.base == STATIC && a.fact.path.startsWith(i.fact.path) ->          // a at or below a static premise: a itself
        if (a.fact.tail == Tail.ANY_TAINT) Pattern(a.fact.copy(mark = MarkSlot.Concrete(t), tail = Tail.ANY), ExclusionSet.Empty)   // `[any]`: no E
        else Pattern(a.fact.copy(mark = MarkSlot.Concrete(t)), a.exclusion)
    a.fact.tail == Tail.EXACT && a.fact.path == i.fact.path ->
        Pattern(PathFact(i.fact.base, i.fact.path, Tail.EXACT, MarkSlot.Concrete(t)), ExclusionSet.Empty)
    else -> Pattern(i.fact.copy(mark = MarkSlot.Concrete(t)), i.exclusion)   // the request chain and kind, mark t
}

/** ap.md §6.2 (Lean policy1). */
fun policy(a: Pattern): Pattern =
    if (a.fact.base == AccessPathBase.Zero) a
    else Pattern(PathFact(a.fact.base, emptyList(), Tail.STAR, MarkSlot.STAR), ExclusionSet.Empty)

/** Generic micro-edge reversal (Lean revEdge, revKinds, MarkRev), unchanged by record read views.
 *  It rejects a must premise and a must conclusion with nonempty exclusion; reverseRecordLeaf handles the supported
 *  native forward must shapes separately (§7.8). A forward must micro target still reverses to ordinary ANY.
 *  MicroEdge.may reads the forward target for pass-rule demand handling. */
fun revEdge(e: PathEdge): PathEdge? {
    if (e.from.tail == Tail.ANY_TAINT) return null                          // generic reversal only
    if (e.to.tail == Tail.ANY_TAINT && (e.toExclusion != ExclusionSet.Empty || e.exclusion != ExclusionSet.Empty))
        return null                                                         // generic reversal only
    val fAbstract = e.to.mark is MarkSlot.Star
    if (!fAbstract && e.from.mark !is MarkSlot.Concrete) return null       // no_rev_of_star_conc
    val (pt, ct) = revTails(e.from.tail, e.to.tail)
    val pm = if (fAbstract) e.from.mark else e.to.mark                     // the new premise never has `*∖X`
    val cm = if (fAbstract) e.to.mark else e.from.mark
    val excl = if (pt == Tail.STAR || ct == Tail.STAR) e.exclusion else ExclusionSet.Empty   // the exclusion goes to the new conclusion (W1)
    return PathEdge(PathFact(e.to.base, e.to.path, pt, pm), PathFact(e.from.base, e.from.path, ct, cm), excl)
}

fun revTails(i: Tail, f: Tail): Pair<Tail, Tail> = when (i) {             // the table of §9.1
    Tail.STAR -> when (f) {
        Tail.STAR -> Tail.STAR to Tail.STAR; Tail.EXACT -> Tail.EXACT to Tail.ANY; Tail.ANY -> Tail.ANY to Tail.ANY
        Tail.ANY_TAINT -> error("S15: a taint edge has an EXACT or ANY premise; a `*` premise has no `[any-taint]` conclusion")
    }
    Tail.ANY -> when (f) {
        Tail.STAR -> Tail.STAR to Tail.STAR; Tail.EXACT -> Tail.EXACT to Tail.ANY; Tail.ANY -> Tail.ANY to Tail.ANY
        Tail.ANY_TAINT -> Tail.ANY to Tail.ANY                               // a conditional source with an `[any]` literal (A1)
    }
    Tail.EXACT -> when (f) {
        Tail.STAR -> Tail.EXACT to Tail.EXACT; Tail.EXACT -> Tail.EXACT to Tail.EXACT; Tail.ANY -> Tail.ANY to Tail.EXACT
        Tail.ANY_TAINT -> Tail.ANY to Tail.EXACT                              // a source result: the premise `[any]` (A1)
    }
    Tail.ANY_TAINT -> error("generic revTails has no must-premise row")   // reverseRecordLeaf handles native must views
}

/** ap.md §8.1 (Subsume.subsumesB, markSubsB): s subsumes n inside one layer. FlowGroup and TaintGroup are its tree form.
 *  An `[any]` s (demand) subsumes every fact at or below its path with its mark. An `[any-taint]/Es` s (normal)
 *  subsumes, with its mark, in its layer, ONLY `[any-taint]` facts: an `[any-taint]/En` fact at its path if `Es ⊆ En`,
 *  and one strictly below its path through an accessor that `Es` admits (A2; argued, ap.md §11.2); NEVER a `$` fact
 *  (DD16, ap-history.md F69: a later demoting cleaner row moves s to the demand layer, and the `$` fact stays normal). */
fun subsumes(s: Conclusion, n: Conclusion): Boolean {
    if (s.fact.base != n.fact.base || s.demand != n.demand || !markSubsumes(s.fact.mark, n.fact.mark)) return false
    return when (s.fact.tail) {
        Tail.ANY -> n.fact.path.startsWith(s.fact.path)
        Tail.ANY_TAINT -> n.fact.tail == Tail.ANY_TAINT && n.fact.path.startsWith(s.fact.path) &&
            if (n.fact.path.size == s.fact.path.size) s.exclusion.isSubsetOf(n.exclusion)
            else s.exclusion.admits(n.fact.path[s.fact.path.size])
        Tail.STAR -> n.fact.tail == Tail.STAR && s.fact.path == n.fact.path && s.exclusion.isSubsetOf(n.exclusion)
        Tail.EXACT -> n.fact.tail == Tail.EXACT && s.fact.path == n.fact.path
    }
}
fun markSubsumes(s: MarkSlot, n: MarkSlot): Boolean = when (s) {
    is MarkSlot.Concrete -> n == s
    is MarkSlot.Star -> n is MarkSlot.Star && s.excluded.isSubsetOf(n.excluded)
}

/** R1 publishes normal singleton summaries except backward zero summaries. */
fun r1Eligible(premise: PremiseKey, g: Conclusion, direction: Direction): Boolean =
    !g.demand && premise is InitialAp && !(direction == Direction.BACKWARD && premise.isZero)

/** F77 selects demand edges by structure, before any transient read-view conversion. */
fun demandSelected(premise: PremiseKey, g: Conclusion, direction: Direction): Boolean =
    g.demand || premise.size > 1 || (direction == Direction.BACKWARD && premise.isZero)

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase

/** The two annotations of a TAINT leaf and the single annotation of a FLOW flag. */
private class SummaryTails<P : TrieLeaf>(
    val exclusion: ExclusionSet,
    val anyExclusion: ExclusionSet = ExclusionSet.Empty,
    val select: (P, star: Boolean, any: Boolean, exact: Boolean) -> P,
)

private fun flowTails(a: FlowTree) = SummaryTails<FlowLeaf>(
    if (a.tail == Tail.STAR) a.exclusion else ExclusionSet.Empty,
    if (a.tail == Tail.ANY_TAINT) a.exclusion else ExclusionSet.Empty,
) { p, star, any, exact ->
    val selected = when (a.tail) {
        Tail.STAR -> star
        Tail.EXACT -> exact
        Tail.ANY, Tail.ANY_TAINT -> any
    }
    if (selected) p else FlowLeaf.NONE
}

private fun taintTails(m: ApManager, a: TaintTree) =
    if (a.anyTail == Tail.STAR) SummaryTails<TaintLeaves>(a.exclusion) { p, star, _, exact ->
        m.taintLeaves(if (exact) p.exact else MarkSet.EMPTY, if (star) p.any else MarkSet.EMPTY)
    } else SummaryTails<TaintLeaves>(ExclusionSet.Empty, a.exclusion) { p, _, any, exact ->
        m.taintLeaves(if (exact) p.exact else MarkSet.EMPTY, if (any) p.any else MarkSet.EMPTY)
    }

/** Preserve full selected leaves and their input annotations. Record demotion occurs after return actions. */
internal fun satisfyingPart(m: ApManager, a: Facts, j: Pattern, mode: ApMode, record: Boolean): Facts? {
    m.cancellation.checkpoint()
    if (a.base != j.fact.base) return null
    check(j.fact.tail != Tail.ANY_TAINT || (mode.restricted && mode.direction == Direction.FORWARD)) {
        "W8 (c): a must-premise is forward restricted"
    }
    val below = record || mode.run1 || (mode.restricted && (j.fact.mark is MarkSlot.Star || j.fact.tail == Tail.STAR))
    val inside = record || mode.restricted || mode.run1
    if (j.fact.tail == Tail.ANY_TAINT && j.fact.mark is MarkSlot.Star) return when (a) {
        is Reach -> null
        is FlowTree -> if (j.fact.mark !is MarkSlot.Star || a.tail != Tail.ANY_TAINT) null
            else definiteMustPart(m, a.root, FlowAlgebra, a.exclusion, j) { it }
                ?.let { m.flowTree(a.base, a.layer, a.exclusion, a.markExclusion, it, a.tail) }
        is TaintTree -> if (a.anyTail != Tail.ANY_TAINT) null
            else definiteMustPart(m, a.root, m.taintAlg, a.exclusion, j) {
                m.taintLeaves(MarkSet.EMPTY, it.any)
            }?.let { markSubPart(m, it, j, mode) }
                ?.let { m.taintTree(a.base, a.layer, it, a.exclusion, a.anyTail) }
    }
    return when (a) {
        is Reach -> a.takeIf { j.fact.base == AccessPathBase.Zero }
        is FlowTree -> if (j.fact.mark !is MarkSlot.Star) null
            else summaryPart(m, a.root, FlowAlgebra, flowTails(a), j, below, inside)
                ?.let { m.flowTree(a.base, a.layer, a.exclusion, a.markExclusion, it, a.tail) }
        is TaintTree -> summaryPart(m, a.root, m.taintAlg, taintTails(m, a), j, below, inside)
            ?.let { markSubPart(m, it, j, mode) }
            ?.let { m.taintTree(a.base, if (mode.markMode == MarkMode.GROUP) Layer.DEMAND else a.layer, it, a.exclusion, a.anyTail) }
    }
}

/** A uniform query requires an actual uniform scope that covers the entire query. */
private fun <P : TrieLeaf> definiteMustPart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, exclusion: ExclusionSet,
    j: Pattern, onlyMust: (P) -> P,
): TrieNode<P>? {
    val path = j.fact.path.toIntArray()
    val spine = ArrayList<P>()
    val at = root.walk(path) { depth, node ->
        m.cancellation.checkpoint()
        spine += if (exclusion.admits(path[depth])) onlyMust(node.leaf) else alg.empty
    }
    if (at != null) spine += if (exclusion.isSubsetOf(j.exclusion)) onlyMust(at.leaf) else alg.empty
    return alg.chain(m, path, spine)
}

private fun markSubPart(m: ApManager, n: TaintNode, j: Pattern, mode: ApMode): TaintNode? {
    val gate = MarkGate(m, j.fact.mark, MarkSlot.STAR, mode)
    return m.taintAlg.mapLeaves(n, m.cancellation) { p ->
        m.taintLeaves(gate.taintMarks(p.exact) ?: MarkSet.EMPTY, gate.taintMarks(p.any) ?: MarkSet.EMPTY)
    }
}

private fun <P : TrieLeaf> summaryPart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, t: SummaryTails<P>, j: Pattern,
    below: Boolean, inside: Boolean,
): TrieNode<P>? {
    val b = if (below) applicablePart(m, root, alg, t, j) else null
    val i = if (inside) insidePart(m, root, alg, t, j) else null
    return if (b == null) i else if (i == null) b else alg.mergeAdd(b, i, m.cancellation)
}

private fun <P : TrieLeaf> applicablePart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, t: SummaryTails<P>, j: Pattern,
): TrieNode<P>? {
    val path = j.fact.path.toIntArray()
    val u = root.walk(path) { _, _ -> m.cancellation.checkpoint() } ?: return null
    m.cancellation.checkpoint()
    val ej = j.exclusion
    val anyAt = ej.isSubsetOf(t.anyExclusion)
    val at = when (j.fact.tail) {
        Tail.STAR -> t.select(u.leaf, ej.isSubsetOf(t.exclusion), anyAt, true)
        Tail.EXACT -> t.select(u.leaf, false, false, true)
        Tail.ANY_TAINT -> t.select(u.leaf, false, anyAt, false)
        Tail.ANY -> t.select(u.leaf, false, true, false)
    }
    val kids = when (j.fact.tail) {
        Tail.STAR -> alg.retainChildren(u, m.cancellation) { ej.admits(it) }
        Tail.EXACT -> null
        Tail.ANY_TAINT -> alg.retainChildren(u, m.cancellation) { ej.admits(it) }
            ?.let { k -> alg.mapLeaves(k, m.cancellation) { t.select(it, false, true, false) } }
        Tail.ANY -> alg.retainChildren(u, m.cancellation) { true }
            ?.let { k -> alg.mapLeaves(k, m.cancellation) { t.select(it, false, true, false) } }
    }
    return alg.withLeaf(kids, at)?.let { alg.prepend(m, m.path(path), it) }
}

private fun <P : TrieLeaf> insidePart(
    m: ApManager, root: TrieNode<P>, alg: LeafAlgebra<P>, t: SummaryTails<P>, j: Pattern,
): TrieNode<P>? {
    val path = j.fact.path.toIntArray()
    val spine = ArrayList<P>()
    val u = root.walk(path) { d, n ->
        m.cancellation.checkpoint()
        spine += t.select(n.leaf, t.exclusion.admits(path[d]), t.anyExclusion.admits(path[d]), false)
    }
    m.cancellation.checkpoint()
    if (u != null) spine += t.select(u.leaf,
        when (j.fact.tail) {
            Tail.EXACT -> true
            Tail.STAR -> t.exclusion.isSubsetOf(j.exclusion)
            Tail.ANY, Tail.ANY_TAINT -> t.exclusion == ExclusionSet.Empty
        },
        j.fact.tail == Tail.EXACT || t.anyExclusion.isSubsetOf(j.exclusion),
        j.fact.tail == Tail.EXACT)
    return alg.chain(m, path, spine)
}

/** One edge for each tail/mark kind, followed by a graft into every path having that kind. */
internal fun applySummaryPart(ops: ApOps, a: Facts, j: InitialAp, g: Facts, mode: ApMode, out: ApOut) {
    val m = ops.manager
    m.cancellation.checkpoint()
    check(a !is FlowTree || g is FlowTree) { "a FLOW fact satisfies only a `*` premise, whose summaries are FLOW" }
    for (kind in leafKinds(m, g, j)) {
        m.cancellation.checkpoint()
        val one = CollectingOut()
        ops.applyCompiledEdge(a, kind.edge, g.layer == Layer.DEMAND, -1, mode, one)
        // F78: applying an excluded abstract target preserves the interest on
        // the caller's original slot before publishing its excluded result.
        for (mark in one.markRequests) {
            m.cancellation.checkpoint()
            out.markRequest(mark)
        }
        for (r in one.results) {
            m.cancellation.checkpoint()
            out.result(kind.graft(r))
        }
    }
}

/** A transient native record uses its Pattern directly, retaining its own exclusions. */
internal fun applyRecordLeafPart(ops: ApOps, a: Facts, view: RecordLeafView, nonSubsumable: Boolean,
                                 mode: ApMode, out: ApOut) {
    val m = ops.manager
    m.cancellation.checkpoint()
    val edge = ops.compiled(summaryEdge(view.premise, view.result))
    val one = CollectingOut()
    ops.applyCompiledEdge(a, edge, view.result.demand, -1, mode, one)
    for (mark in one.markRequests) {
        m.cancellation.checkpoint()
        out.markRequest(mark)
    }
    for (r in one.results) {
        m.cancellation.checkpoint()
        out.result(if (nonSubsumable) m.selectedProtection(r, null) else r)
    }
}

private class SummaryLeafKind(val edge: CompiledEdge, val graft: (Facts) -> Facts)

private fun leafKinds(m: ApManager, g: Facts, j: InitialAp): List<SummaryLeafKind> {
    val jOwn = j.tail == Tail.ANY_TAINT
    val inputShared = if (jOwn) ExclusionSet.Empty else j.exclusion
    fun edge(tail: Tail, mark: MarkSlot, exclusion: ExclusionSet, toExclusion: ExclusionSet = ExclusionSet.Empty) =
        CompiledEdge(j.base, j.pathData, j.tail, j.mark, g.base, null, tail, mark,
            m.intern(exclusion),
            m.intern(if (jOwn) j.exclusion else ExclusionSet.Empty), m.intern(toExclusion))
    return when (g) {
        is Reach -> listOf(SummaryLeafKind(edge(Tail.EXACT, MarkSlot.Concrete(TaintMark.ZERO), ExclusionSet.Empty)) { it })
        is FlowTree -> listOf(SummaryLeafKind(edge(g.tail, MarkSlot.Star(g.markExclusion),
            if (g.tail == Tail.STAR || g.tail == Tail.EXACT) inputShared.union(g.exclusion) else inputShared,
            if (g.tail == Tail.ANY_TAINT) g.exclusion else ExclusionSet.Empty)) {
            graftSummary(m, g.root, { p -> p == FlowLeaf.LEAF }, it)
        })
        is TaintTree -> {
            val all = m.taintAlg.foldAll(g.root, m.cancellation)
            val anyTail = g.anyTail
            val kinds = ArrayList<SummaryLeafKind>()
            for (id in all.exact.ids) {
                m.cancellation.checkpoint()
                val mark = TaintMark(id)
                kinds += SummaryLeafKind(edge(Tail.EXACT, MarkSlot.Concrete(mark), inputShared)) {
                    graftSummary(m, g.root, { p -> mark in p.exact }, it)
                }
            }
            for (id in all.any.ids) {
                m.cancellation.checkpoint()
                val mark = TaintMark(id)
                val shared = if (anyTail == Tail.STAR) inputShared.union(g.exclusion) else inputShared
                val own = if (anyTail == Tail.ANY_TAINT) g.exclusion else ExclusionSet.Empty
                kinds += SummaryLeafKind(edge(anyTail, MarkSlot.Concrete(mark), shared, own)) {
                    graftSummary(m, g.root, { p -> mark in p.any }, it)
                }
            }
            kinds
        }
    }
}

private fun <G : TrieLeaf> graftSummary(m: ApManager, g: TrieNode<G>, occurs: (G) -> Boolean, r: Facts): Facts =
    when (r) {
        is Reach -> r
        is FlowTree -> r.withRoot(checkNotNull(FlowAlgebra.graft(g, occurs, r.root, m.cancellation)))
        is TaintTree -> m.taintTree(r.base, r.layer,
            checkNotNull(m.taintAlg.graft(g, occurs, r.root, m.cancellation)), r.exclusion, r.anyTail,
            r.nonSubsumable?.let { m.taintAlg.graft(g, occurs, it, m.cancellation) })
    }

/** Matching is supplied by the caller. W7 makes each complete concrete member return the same target. */
internal fun applyCombinationPart(
    manager: ApManager, parts: List<Pair<Facts, InitialAp>>, g: TaintTree, mode: ApMode, out: ApOut,
) {
    manager.cancellation.checkpoint()
    check(parts.size >= 2)
    val layers = ArrayList<Layer>(parts.size)
    for ((part, _) in parts) {
        manager.cancellation.checkpoint()
        check(part is TaintTree)
        layers += part.layer
    }
    applyMatchedCombinationPart(manager, layers, g, out)
}

/** E6's full member matcher has checked TAINT inputs. Their roots do not affect this transfer. */
internal fun applyMatchedCombinationPart(
    manager: ApManager, linkLayers: List<Layer>, g: TaintTree, out: ApOut,
) {
    manager.cancellation.checkpoint()
    check(linkLayers.size >= 2)
    var layer = g.layer
    for (linkLayer in linkLayers) {
        manager.cancellation.checkpoint()
        if (linkLayer == Layer.DEMAND) layer = Layer.DEMAND
    }
    out.result(g.withLayer(layer))
}

/** Remove identical annotated leaves; preserve the other leaves without record demotion. */
internal fun withoutPart(manager: ApManager, c: Facts, part: Facts): Facts? {
    manager.cancellation.checkpoint()
    return when {
        c.base != part.base -> c
        c is TaintTree && part is TaintTree ->
            if (c.layer != part.layer || (part.root.hasAny &&
                    (part.exclusion != c.exclusion || part.anyTail != c.anyTail))) c
            else manager.taintAlg.minusNode(c.root, part.root, manager.cancellation)
                ?.let { if (it === c.root) c else c.withRoot(it) }
        c.groupKey != part.groupKey -> c
        c is Reach -> if (part is Reach && part.layer == c.layer) null else c
        c is FlowTree && part is FlowTree -> FlowAlgebra.minusNode(c.root, part.root, manager.cancellation)
            ?.let { if (it === c.root) c else c.withRoot(it) }
        else -> c
    }
}

package org.opentaint.dataflow.bidi.ap


/** Shared facade. All walk state is local to the call. */
class ApOps(val manager: ApManager) {
    fun run1Cover(f: Facts, emit: (Facts) -> Unit) = run1CoverFacts(manager, f, emit)

    /** Scalar callers must not silently demote exact members of a mixed group. */
    fun run1Cover(f: Facts): Facts {
        var only: Facts? = null
        run1Cover(f) { value -> check(only == null) { "Mixed E-bearing facts require the callback cover" }; only = value }
        return checkNotNull(only)
    }
    fun applyEdge(c: Facts, premise: PremiseKey, e: PathEdge, statementEdge: Boolean,
                  mode: ApMode, out: ApOut, may: Boolean = false,
                  unchangedStaticInitial: InitialAp? = null, ruleAssignment: Boolean = false) {
        check(unchangedStaticInitial == null ||
            (unchangedStaticInitial === premise && unchangedStaticInitial.manager === manager)) {
            "The ordinary static gate needs this edge's original initial"
        }
        val ce = compiled(e)
        val from = (e.from.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        val assigned = (e.to.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        val protect = ruleAssignment && from != null && assigned != null &&
            (from == assigned || premise.members.any {
                (it.mark as? MarkSlot.Concrete)?.mark?.let { atom -> manager.marks.runtimeAtom(atom, mode.markMode) } == assigned && from != assigned
            })
        val sink = if (!protect) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, manager.markSetOf(assigned!!)))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        applyCompiledEdge(c, ce, may, staticIdentityDepth(c, premise, ce, statementEdge, mode), mode, sink,
            unchangedStaticInitial)
    }

    internal fun compiled(e: PathEdge): CompiledEdge {
        val old = e.compiled
        if (old != null && (old.toPath == null || old.toPath.manager === manager)) return old
        return manager.compile(e).also { e.compiled = it }
    }

    internal fun applyCompiledEdge(c: Facts, ce: CompiledEdge, edgeDemand: Boolean,
                                   staticAt: Int, mode: ApMode, out: ApOut,
                                   unchangedStaticInitial: InitialAp? = null) {
        manager.transportProtection(c, out) { part, sink ->
            applyCompiledEdgeRaw(part, ce, edgeDemand, staticAt, mode, sink, unchangedStaticInitial)
        }
    }

    private fun applyCompiledEdgeRaw(c: Facts, ce: CompiledEdge, edgeDemand: Boolean,
                                    staticAt: Int, mode: ApMode, out: ApOut,
                                    unchangedStaticInitial: InitialAp?) {
        manager.cancellation.checkpoint()
        if (c.base != ce.fromBase) return
        val sink = out.run1Policy(manager, mode)
        val app = EdgeApplication(manager, ce, edgeDemand, mode, sink, unchangedStaticInitial)
        when (c) {
            is Reach -> app.reach(c)
            is FlowTree -> app.flow(c, staticAt)
            is TaintTree -> app.taint(c)
        }
        app.results.flush(sink)
    }

    fun satisfying(a: Facts, j: InitialAp, mode: ApMode, record: Boolean = false): Facts? =
        satisfying(a, j.toPattern(), mode, record)

    fun satisfying(a: Facts, j: Pattern, mode: ApMode, record: Boolean = false): Facts? =
        satisfyingPart(manager, a, j, mode, record)?.let { retainProtection(a, it, manager.cancellation) }

    fun applySummary(a: Facts, j: InitialAp, g: Facts, mode: ApMode, out: ApOut,
                     original: PremiseKey? = null) {
        val masks = (g as? TaintTree)?.protectedPart()?.let { protected ->
            ProtectionOutputs(manager).also { applySummaryPart(this, a.withoutProtection(), j, protected, mode, it) }
        }
        val incoming = (j.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        var restored = MarkSet.EMPTY
        if (original != null && incoming != null) {
            for (i in original.members) {
                val origin = (i.mark as? MarkSlot.Concrete)?.mark?.let { manager.marks.runtimeAtom(it, mode.markMode) } ?: continue
                if (origin != incoming) restored += origin
            }
        }
        val restoredMarks = manager.intern(restored)
        val sink = if (masks == null && restoredMarks.isEmpty) out else object : ApOut {
            override fun result(f: Facts) {
                val flagged = masks?.attach(f) ?: f
                out.result(if (restoredMarks.isEmpty) flagged else manager.selectedProtection(flagged, restoredMarks))
            }
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        applySummaryPart(this, a, j, g, mode, sink)
    }

    fun applyRecordLeaf(a: Facts, view: RecordLeafView, nonSubsumable: Boolean,
                        mode: ApMode, out: ApOut, original: PremiseKey? = null) {
        val trigger = (view.premise.fact.mark as? MarkSlot.Concrete)?.mark
            ?.let { manager.marks.runtimeAtom(it, mode.markMode) }
        var restored = MarkSet.EMPTY
        if (original != null && trigger != null) for (i in original.members) {
            val origin = (i.mark as? MarkSlot.Concrete)?.mark
                ?.let { manager.marks.runtimeAtom(it, mode.markMode) } ?: continue
            if (origin != trigger) restored += origin
        }
        val sink = if (restored.isEmpty) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, restored))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        applyRecordLeafPart(this, a, view, nonSubsumable, mode, sink)
    }

    fun applyCombination(parts: List<Pair<Facts, InitialAp>>, g: TaintTree, mode: ApMode, out: ApOut) =
        applyCombinationPart(manager, parts, g, mode, out.run1Policy(manager, mode))

    /** Used only after E6's full matching and TAINT guards. Caller layers remain in the resume context. */
    internal fun applyMatchedCombination(linkLayers: List<Layer>, g: TaintTree, out: ApOut) =
        applyMatchedCombinationPart(manager, linkLayers, g, out)

    fun without(c: Facts, part: Facts): Facts? = withoutPart(manager, c, part)
    fun reverse(e: PathEdge): PathEdge? = revEdge(e)
    fun leaves(f: Facts): Sequence<Pattern> = leafViews(manager, f)
    fun leavesNear(f: Facts, p: IntArray): Sequence<Pattern> = nearLeafViews(manager, f, p)

    fun clean(c: Facts, premise: PremiseKey, cl: Cleaner, mode: ApMode, out: ApOut) {
        val protect = c.base == cl.base
        val sink = if (!protect) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, cl.mark?.let { manager.markSetOf(manager.marks.runtimeAtom(it, mode.markMode)) }))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        manager.transportProtection(c, sink) { part, target ->
            cleanFacts(manager, part, premise, cl, mode, target.run1Policy(manager, mode))
        }
    }

    /** Selected FULL mask; null Cleaner.mark retains its all-mark meaning on the scalar API. */
    fun cleanSelectedFullMask(c: Facts, premise: PremiseKey, geometry: Cleaner, selected: MarkSet,
                              mode: ApMode, request: (MarkSet) -> Unit, out: ApOut) {
        check(geometry.mark != null) { "A FULL cleanup block must have selected-mark geometry" }
        val sink = if (c.base != geometry.base) out else object : ApOut {
            override fun result(f: Facts) = out.result(manager.selectedProtection(f, selected))
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        }
        val protected = (c as? TaintTree)?.protectedPart()
        val masks = protected?.let { part -> ProtectionOutputs(manager).also {
            cleanSelectedFullMask(manager, part, geometry, selected, mode, {}, it.run1Policy(manager, mode))
        } }
        val target = if (masks == null) sink else object : ApOut {
            override fun result(f: Facts) = sink.result(masks.attach(f))
            override fun markRequest(mark: TaintMark) = sink.markRequest(mark)
        }
        cleanSelectedFullMask(manager, c, geometry, selected, mode, request, target.run1Policy(manager, mode))
    }

    fun filter(c: Facts, f: TypeFilter): Facts? = filterFacts(manager, c, f)?.let { retainProtection(c, it, manager.cancellation) }
    fun limit(c: Facts, fieldLimit: Int, out: ApOut) = manager.transportProtection(c, out) { part, sink ->
        limitFacts(manager, part, fieldLimit, sink)
    }
    /** Pass the original initial only when the run-1 static catalog covers this check. */
    fun checkMark(c: Facts, p: Pattern, mode: ApMode,
                  unchangedStaticInitial: InitialAp? = null): MarkCheck =
        when (val result = markCheckFacts(manager, c, p, mode, unchangedStaticInitial)) {
            is MarkCheck.Holds -> MarkCheck.Holds(retainProtection(c, result.facts, manager.cancellation))
            else -> result
        }
    fun withoutMarks(c: Facts, marks: MarkSet): Facts? = withoutMarksPart(manager, c, marks)

    fun targetTree(target: PathFact, layer: Layer, mode: ApMode? = null): Facts {
        check(target.mark is MarkSlot.Concrete && target.tail != Tail.STAR) { "W7: a target must be concrete and exact or any" }
        val value = manager.factsOf(target, ExclusionSet.Empty, layer)
        return if (mode == null) value else manager.runtimeFact(value, mode)
    }

    fun zero(layer: Layer): Reach = Reach.of(layer)
    fun startFact(i: InitialAp): Facts = initialFacts(manager, i)
    fun startFact(i: InitialAp, mode: ApMode): Facts = manager.runtimeFact(initialFacts(manager, i), mode)
    fun runtimeFact(f: Facts, mode: ApMode): Facts = manager.runtimeFact(f, mode)
    fun policy(added: Facts): InitialAp = policyInitial(manager, added)
    fun emit(d: DemandPattern, added: Facts, policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = manager.marks)): List<InitialAp> = emitInitials(this, d, added, policy)
    fun restrictReference(j: InitialAp, g: Facts, d: DemandPattern): List<Conclusion> = restrictRaw(this, j, g, d)
    fun restrict(j: InitialAp, g: Facts, d: DemandPattern, policy: RestrictedInitialPolicy = RestrictedInitialPolicy(direction = Direction.FORWARD, catalog = manager.marks)): List<Facts> = restrictFacts(this, j, g, d, policy)
    fun demandPart(premise: PremiseKey, g: Facts, direction: Direction): Facts? =
        selectDemand(manager, premise, g, direction)
}

private fun staticIdentityDepth(c: Facts, premise: PremiseKey, ce: CompiledEdge,
                                statementEdge: Boolean, mode: ApMode): Int {
    if (c !is FlowTree || c.layer != Layer.NORMAL || !mode.run1 || !statementEdge) return -1
    if (c.base != STATIC || ce.fromBase != STATIC) return -1
    val i = premise as? InitialAp ?: return -1
    if (i.base != STATIC || i.tail != Tail.STAR || i.mark != MarkSlot.STAR) return -1
    val q = i.pathData
    if (!(q.isEmpty() || (q.size == 1 && q[0].isClass()))) return -1
    if (ce.fromPathData.size <= q.size || !ce.fromPathData.startsWith(q)) return -1
    return q.size
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorIdx

internal fun ApManager.compile(e: PathEdge): CompiledEdge = CompiledEdge(
    e.from.base, e.from.path.toIntArray(), e.from.tail, e.from.mark,
    e.to.base, path(e.to.path), e.to.tail, e.to.mark,
    intern(e.exclusion), intern(e.fromExclusion), intern(e.toExclusion))

/** Immutable edge form. The from-path array belongs to this value. */
internal class CompiledEdge(
    val fromBase: AccessPathBase, fromPath: IntArray, val fromTail: Tail, val fromMark: MarkSlot,
    val toBase: AccessPathBase, val toPath: PathNode?, val toTail: Tail, val toMark: MarkSlot,
    val exclusion: ExclusionSet,
    val fromExclusion: ExclusionSet = ExclusionSet.Empty,
    val toExclusion: ExclusionSet = ExclusionSet.Empty,
) {
    internal val fromPathData = fromPath.copyOf()
    val fromPath: IntArray get() = fromPathData.copyOf()

    init {
        check(fromMark !is MarkSlot.Star || fromMark.excluded.isEmpty) { "S7: a premise cannot exclude marks" }
        check(toMark !is MarkSlot.Concrete || fromMark is MarkSlot.Concrete) { "S7: a concrete target needs a concrete premise" }
        check(fromTail != Tail.EXACT || toTail != Tail.STAR || fromMark is MarkSlot.Star) {
            "A concrete exact premise cannot have a STAR target"
        }
        check(toTail != Tail.ANY_TAINT || toMark is MarkSlot.Concrete || fromMark is MarkSlot.Star) {
            "An abstract must target needs a FLOW relation"
        }
        check(fromTail == Tail.STAR || toTail == Tail.STAR || exclusion == ExclusionSet.Empty) { "W1: only STAR sides have shared E" }
        check(fromTail == Tail.ANY_TAINT || fromExclusion == ExclusionSet.Empty) { "A2: only a must premise has own E" }
        check(toTail == Tail.ANY_TAINT || toExclusion == ExclusionSet.Empty) { "A2: only a must target has own E" }
    }
}

/** The tree form of concat. Field cuts belong to the caller. */
internal class EdgeApplication(private val m: ApManager, private val ce: CompiledEdge,
                               private val edgeDemand: Boolean, private val mode: ApMode,
                               private val out: ApOut, private val unchangedStaticInitial: InitialAp? = null) {
    val results = Results(m, ce.toBase)
    private val gate = MarkGate(m, ce.fromMark, ce.toMark, mode)
    private val admitsRest = { a: AccessorIdx ->
        val premiseAdmits = when (ce.fromTail) {
            Tail.EXACT -> false
            Tail.ANY_TAINT -> ce.fromExclusion.admits(a)
            else -> ce.exclusion.admits(a)
        }
        premiseAdmits && (ce.toTail != Tail.STAR || ce.exclusion.admits(a))
    }
    private val aboveTail = if (ce.toTail == Tail.EXACT) Tail.EXACT else Tail.ANY
    private val mustAboveTail = when (ce.toTail) {
        Tail.EXACT -> Tail.EXACT
        Tail.ANY -> Tail.ANY
        Tail.STAR, Tail.ANY_TAINT -> Tail.ANY_TAINT
    }
    private val aboveExclusion = if (ce.toTail == Tail.ANY_TAINT) ce.toExclusion else ce.exclusion
    private var requested = false

    fun reach(c: Reach) {
        check(ce.fromPathData.isEmpty() && !ce.fromTail.isAny)
        gate.taintMarks(m.markSetOf(TaintMark.ZERO))?.let { put(c.layer or edgeDemand, ce.toTail, it, ce.toExclusion) }
    }

    fun flow(c: FlowTree, staticAt: Int) {
        // F78: exclusion creation also creates interest on the original abstract
        // slot. Do this before the positional/mark tests and before any output.
        // The engine's collector applies the normal-origin and static-root guards.
        if (mode.run1) (ce.toMark as? MarkSlot.Star)?.excluded?.data?.forEach { id ->
            m.cancellation.checkpoint()
            out.markRequest(m.marks.runtimeAtom(TaintMark(id), mode.markMode))
            if ((ce.fromMark as? MarkSlot.Concrete)?.mark?.id == id) requested = true
        }
        val mx = gate.flowMarks(c.markExclusion)
        val exact = c.tail == Tail.EXACT
        val must = c.tail == Tail.ANY_TAINT
        val normal = c.tail != Tail.ANY
        val writeKeep = ce.fromBase == ce.toBase && ce.fromTail == Tail.STAR &&
            ce.toTail == Tail.STAR && ce.fromPathData.contentEquals(ce.toPath?.toIntArray() ?: EMPTY_PATH) &&
            ce.exclusion != ExclusionSet.Empty
        val layer = c.layer or edgeDemand
        val unchanged = if (mode.run1 && mode.markMode == MarkMode.FULL) unchangedStaticFlowPath(c, unchangedStaticInitial) else null
        val u = c.root.walk(ce.fromPathData) { d, n ->
            m.cancellation.checkpoint()
            if (n.leaf.isEmpty || (normal && !c.exclusion.admits(ce.fromPathData[d]))) return@walk
            if (normal && d == staticAt) {
                // Prescan catalog emission replaces the old position request. This parent gives no fact.
            } else if (!exact || writeKeep) flowHit(mx, c, { !sameFlowLeaf(m, unchanged, ce.fromPathData, d) }) {
                if (must) {
                    val tail = if (layer == Layer.DEMAND) Tail.ANY else mustAboveTail
                    results.flow(if (tail == Tail.ANY) Layer.DEMAND else layer,
                        if (tail == Tail.ANY || tail == Tail.EXACT) ExclusionSet.Empty else aboveExclusion, it, flagAtTarget(), tail)
                } else results.flow(Layer.DEMAND, ExclusionSet.Empty, it, flagAtTarget())
            }
        } ?: return
        val kids = FlowAlgebra.retainChildren(u, m.cancellation, admitsRest)
        when (ce.toTail) {
            Tail.STAR -> {
                if (kids != null) flowHit(mx, c, { changedFlowSubtree(m, kids, ce.fromPathData, unchanged) }) {
                    if (layer == Layer.DEMAND && (exact || must))
                        results.flow(Layer.DEMAND, ExclusionSet.Empty, it, FlowAlgebra.prepend(m, ce.toPath, kids), Tail.ANY)
                    else results.flow(layer, c.exclusion, it, FlowAlgebra.prepend(m, ce.toPath, kids), c.tail)
                }
                if (!u.leaf.isEmpty) flowHit(mx, c, {
                    !sameFlowLeaf(m, unchanged, ce.fromPathData, ce.fromPathData.size)
                }) {
                    if (mode.run1 && ce.exclusion != ExclusionSet.Empty && c.tail != Tail.ANY)
                        results.flow(Layer.DEMAND, ExclusionSet.Empty, it, flagAtTarget(), c.tail)
                    else if (layer == Layer.DEMAND && (exact || must))
                        results.flow(Layer.DEMAND, ExclusionSet.Empty, it, flagAtTarget(), Tail.ANY)
                    else results.flow(layer, c.exclusion.union(ce.exclusion), it, flagAtTarget(), c.tail)
                }
            }
            else -> if (kids != null || !u.leaf.isEmpty) flowHit(mx, c, {
                (!u.leaf.isEmpty && !sameFlowLeaf(m, unchanged, ce.fromPathData, ce.fromPathData.size)) ||
                    (kids != null && changedFlowSubtree(m, kids, ce.fromPathData, unchanged))
            }) {
                val tail = if (layer == Layer.DEMAND && ce.toTail != Tail.ANY) Tail.ANY else ce.toTail
                val exclusion = when (tail) {
                    Tail.ANY_TAINT -> ce.toExclusion
                    Tail.EXACT -> ExclusionSet.Empty
                    else -> ExclusionSet.Empty
                }
                results.flow(if (tail == Tail.ANY) Layer.DEMAND else layer, exclusion, it, flagAtTarget(), tail)
            }
        }
    }

    private inline fun flowHit(mx: MarkExclusions?, c: FlowTree, changed: () -> Boolean, add: (MarkExclusions) -> Unit) {
        if (mx != null) { add(mx); return }
        val mark = gate.flowRequest(c.markExclusion) ?: return
        if (mode.run1 && !requested && changed()) { out.markRequest(mark); requested = true }
    }

    fun taint(c: TaintTree) {
        val layer = c.layer or edgeDemand
        val must = c.anyTail == Tail.ANY_TAINT
        val e = c.exclusion
        val u = c.root.walk(ce.fromPathData) { d, n ->
            m.cancellation.checkpoint()
            if (!e.admits(ce.fromPathData[d])) return@walk
            gate.taintMarks(n.leaf.any)?.let {
                if (must) put(layer, mustAboveTail, it, aboveExclusion)
                else put(Layer.DEMAND, aboveTail, it)
            }
        } ?: return
        when (ce.toTail) {
            Tail.STAR -> {
                m.taintAlg.retainChildren(u, m.cancellation, admitsRest)?.let { kids ->
                    gateTree(kids)?.let { results.taint(layer, m.taintAlg.prepend(m, ce.toPath, it), e, c.anyTail) }
                }
                gate.taintMarks(u.leaf.exact)?.let { put(layer, Tail.EXACT, it) }
                gate.taintMarks(u.leaf.any)?.let {
                    when (c.anyTail) {
                        Tail.STAR, Tail.ANY_TAINT -> put(layer, c.anyTail, it, e.union(ce.exclusion))
                        Tail.ANY -> put(Layer.DEMAND, Tail.ANY, it)
                        else -> error("Nonexact TAINT header")
                    }
                }
            }
            else -> {
                val all = m.taintAlg.foldLeaves(u, m.cancellation, admitsRest)
                gate.taintMarks(all.exact + all.any)?.let { put(layer, ce.toTail, it, ce.toExclusion) }
            }
        }
    }

    private fun put(layer: Layer, tail: Tail, marks: MarkSet, exclusion: ExclusionSet = ExclusionSet.Empty) {
        val resultLayer = if (tail == Tail.ANY) Layer.DEMAND else layer
        if (ce.toBase == AccessPathBase.Zero) { results.reach(resultLayer); return }
        val leaf = when (tail) {
            Tail.EXACT -> m.taintLeaves(marks, MarkSet.EMPTY)
            Tail.STAR, Tail.ANY, Tail.ANY_TAINT -> m.taintLeaves(MarkSet.EMPTY, marks)
        }
        val hasExclusion = tail == Tail.STAR || tail == Tail.ANY_TAINT
        val cover = mode.run1 && hasExclusion && exclusion != ExclusionSet.Empty
        results.taint(if (cover) Layer.DEMAND else resultLayer,
            m.taintAlg.prepend(m, ce.toPath, m.taintAlg.leafNode(leaf)),
            if (cover || !hasExclusion) ExclusionSet.Empty else exclusion,
            if (tail == Tail.EXACT) Tail.ANY_TAINT else tail)
    }

    private fun gateTree(n: TaintNode): TaintNode? =
        if (ce.fromMark == MarkSlot.STAR && ce.toMark == MarkSlot.STAR) n
        else m.taintAlg.mapLeaves(n, m.cancellation) { p ->
            m.taintLeaves(gate.taintMarks(p.exact) ?: MarkSet.EMPTY, gate.taintMarks(p.any) ?: MarkSet.EMPTY)
        }

    private fun flagAtTarget(): FlowNode = FlowAlgebra.prepend(m, ce.toPath, FlowAlgebra.LEAF_NODE)
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase

/** An entry command. Layer is not part of the interned premise identity. */
data class AdmittedInitial(val initial: InitialAp, val layer: Layer)

/** Query-local output; inspecting coverage does not intern hypothetical initials. */
data class InitialEmission(val pattern: Pattern, val layer: Layer)

private fun intrinsicInitialLayer(tail: Tail, mark: MarkSlot, zero: Boolean): Layer = when {
    zero -> Layer.NORMAL
    tail == Tail.ANY -> Layer.DEMAND
    tail == Tail.STAR && mark is MarkSlot.Concrete -> Layer.DEMAND
    else -> Layer.NORMAL
}

fun intrinsicInitialLayer(initial: InitialAp): Layer =
    intrinsicInitialLayer(initial.tail, initial.mark, initial.isZero)

fun intrinsicInitialLayer(pattern: Pattern): Layer =
    intrinsicInitialLayer(pattern.fact.tail, pattern.fact.mark, pattern.fact.base == AccessPathBase.Zero)

/** Concrete data inherits its actual support. FLOW and ZERO keep their old entry policy. */
fun admissionLayer(emitted: Pattern, actual: Pattern, supplied: Layer): Layer {
    val intrinsic = intrinsicInitialLayer(emitted)
    if (emitted.fact.base == AccessPathBase.Zero || emitted.fact.mark is MarkSlot.Star) return intrinsic
    val loss = emitted.fact.tail == Tail.EXACT && actual.fact.tail == Tail.ANY
    return intrinsic or (supplied == Layer.DEMAND || loss)
}

/** Canonicalize before seen-bit admission, including intrinsic STAR and run-1 policies. */
fun canonicalAdmission(initial: InitialAp, supplied: Layer, mode: ApMode? = null): AdmittedInitial {
    val ordinary = intrinsicInitialLayer(initial) or (supplied == Layer.DEMAND)
    val run1Demand = mode?.run1 == true && (initial.base == STATIC ||
        !initial.isZero && initial.mark is MarkSlot.Concrete && mode.markMode == MarkMode.GROUP)
    return AdmittedInitial(initial, ordinary or run1Demand)
}

fun existingZeroAdmission(initial: InitialAp): AdmittedInitial {
    require(initial.isZero) { "ZERO admission requires the existing canonical ZERO key" }
    return AdmittedInitial(initial, Layer.NORMAL)
}

package org.opentaint.dataflow.bidi.ap

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.ap.ifds.access.util.AccessorInterner.Companion.isFieldAccessor

/** One run's pure C2 policy. Image tests inspect templates; they never intern hypothetical facts. */
class RestrictedInitialPolicy(
    val run: Int = 2,
    val fieldLimit: Int = Int.MAX_VALUE,
    val direction: Direction = if (run % 2 == 0) Direction.BACKWARD else Direction.FORWARD,
    private val catalog: MarkTable? = null,
) {
    init { require(run >= 2 && fieldLimit >= 1) }

    fun emit(demand: Pattern, actual: Pattern): Pattern? {
        if (!validDemand(demand)) return null
        val d = normalizeDemandFieldExclusion(demand)
        if (d.fact.base != actual.fact.base || !markSub(d.fact.mark, actual.fact.mark, catalog)) return null
        if (d.fact.base == AccessPathBase.Zero && !canonicalZero(actual)) return null
        if (!fitsBudget(d) || !fitsBudget(actual)) return null
        // Only a concrete MAY witness can supply a provisional exact data point.
        if (d.fact.tail == Tail.EXACT && actual.fact.tail == Tail.ANY && d.fact.mark is MarkSlot.Star) return null
        val p = d.fact.path
        val q = actual.fact.path
        val mark = boundMark(d.fact.mark, actual.fact.mark)
        fun result(path: List<Int>, tail: Tail, e: ExclusionSet = ExclusionSet.Empty): Pattern? {
            val value = Pattern(PathFact(d.fact.base, path, tail, mark), e)
            return value.takeIf(::legalInitial)
        }
        if (q == p) return when (d.fact.tail) {
            Tail.ANY -> when (actual.fact.tail) {
                Tail.STAR -> null
                Tail.EXACT -> result(p, Tail.EXACT)
                Tail.ANY -> result(p, Tail.ANY)
                Tail.ANY_TAINT -> result(p, Tail.ANY_TAINT, actual.exclusion)
            }
            Tail.STAR, Tail.EXACT -> result(p, Tail.EXACT)
            Tail.ANY_TAINT -> null // A demand entry never has a MUST tail.
        }
        if (q.startsWith(p)) {
            if (!d.tailAdmits(q.drop(p.size))) return null
            return when (d.fact.tail) {
                Tail.STAR -> if (run == 2) result(p, Tail.STAR, d.exclusion) else null
                Tail.ANY -> {
                    val end = firstFieldEnd(d.fact.base, p, q) ?: return null
                    val tail = if (mark is MarkSlot.Concrete && actual.fact.tail == Tail.EXACT && end == q.size)
                        Tail.EXACT else Tail.STAR
                    result(q.take(end), tail)
                }
                else -> null
            }
        }
        if (p.startsWith(q) && actual.tailAdmits(p.drop(q.size))) return when (d.fact.tail) {
            Tail.ANY -> when (actual.fact.tail) {
                Tail.ANY -> result(p, Tail.ANY)
                Tail.ANY_TAINT -> result(p, Tail.ANY_TAINT, d.exclusion)
                else -> null
            }
            Tail.STAR, Tail.EXACT -> result(p, Tail.EXACT)
            Tail.ANY_TAINT -> null
        }
        return null
    }

    /** Preserve concrete support without interning an AP. Actuals are legal ApOps.leaves views:
     * exact concrete leaves have Empty E even in a mixed tree; MAY headers also have Empty E. */
    fun emitAdmission(demand: Pattern, actual: Pattern, actualLayer: Layer): InitialEmission? {
        val emitted = emit(demand, actual) ?: return null
        return InitialEmission(emitted, admissionLayer(emitted, actual, actualLayer))
    }

    /** Complete structural output image, including the non-idempotent run-2 requested STAR. */
    fun canEmitInitial(demand: Pattern, initial: Pattern): Boolean {
        if (!validDemand(demand)) return false
        val d = normalizeDemandFieldExclusion(demand)
        if (!legalInitial(initial) || !fitsBudget(d) || d.fact.base != initial.fact.base ||
            !renderedMark(d.fact.mark, initial.fact.mark)) return false
        val p = d.fact.path
        val q = initial.fact.path
        if (q == p) return when (initial.fact.tail) {
            Tail.EXACT -> initial.exclusion == ExclusionSet.Empty && d.fact.tail != Tail.ANY_TAINT
            Tail.ANY -> d.fact.tail == Tail.ANY && initial.exclusion == ExclusionSet.Empty
            Tail.ANY_TAINT -> d.fact.tail == Tail.ANY
            Tail.STAR -> run == 2 && d.fact.tail == Tail.STAR && initial.exclusion == d.exclusion &&
                p.count { it.isCounted() } < fieldLimit &&
                !(initial.fact.base == STATIC && p.size == 1)
        }
        if (d.fact.tail != Tail.ANY || !q.startsWith(p) || !d.tailAdmits(q.drop(p.size))) return false
        val end = firstFieldEnd(d.fact.base, p, q) ?: return false
        return end == q.size && initial.exclusion == ExclusionSet.Empty &&
            (initial.fact.tail == Tail.STAR || initial.fact.tail == Tail.EXACT && initial.fact.mark is MarkSlot.Concrete)
    }

    /** Summary keys are normalized, but the containment test belongs to their raw preimage. */
    fun canStoreInitial(entry: Pattern, stored: Pattern): Boolean {
        if (!validDemand(entry)) return false
        fun fits(raw: Pattern): Boolean = canEmitInitial(entry, raw) && insideDemand(raw, entry, catalog)
        if (fits(stored)) return true
        return stored.fact.mark is MarkSlot.Star && stored.fact.tail == Tail.STAR &&
            stored.exclusion == ExclusionSet.Empty && fits(stored.copy(fact = stored.fact.copy(tail = Tail.EXACT)))
    }

    private fun boundMark(required: MarkSlot, actual: MarkSlot): MarkSlot =
        if (required is MarkSlot.Concrete && catalog?.isGroup(required.mark) == true &&
            actual is MarkSlot.Concrete) actual else required

    private fun renderedMark(required: MarkSlot, rendered: MarkSlot): Boolean =
        if (required is MarkSlot.Star) rendered == required
        else rendered is MarkSlot.Concrete && markSub(required, rendered, catalog)

    private fun fitsBudget(p: Pattern): Boolean = p.fact.path.count { it.isCounted() } <= fieldLimit

    private fun validDemand(p: Pattern): Boolean =
        !(p.fact.tail == Tail.EXACT && p.fact.mark is MarkSlot.Concrete && p.exclusion != ExclusionSet.Empty) &&
            (p.fact.base != AccessPathBase.Zero || canonicalZero(p))

    private fun canonicalZero(p: Pattern): Boolean = p.fact.path.isEmpty() && p.fact.tail == Tail.EXACT &&
        p.exclusion == ExclusionSet.Empty && p.fact.mark == MarkSlot.Concrete(TaintMark.ZERO)

    private fun legalInitial(p: Pattern): Boolean {
        if (!fitsBudget(p) || p.fact.tail == Tail.ANY_TAINT && direction == Direction.BACKWARD) return false
        if (p.fact.mark is MarkSlot.Concrete && catalog?.isGroup(p.fact.mark.mark) == true) return false
        if (p.fact.tail != Tail.STAR && p.fact.tail != Tail.ANY_TAINT && p.exclusion != ExclusionSet.Empty) return false
        if (p.fact.mark is MarkSlot.Star && !p.fact.mark.excluded.isEmpty) return false
        if (p.fact.base == AccessPathBase.Zero) return p.fact.path.isEmpty() && p.fact.tail == Tail.EXACT &&
            p.exclusion == ExclusionSet.Empty && p.fact.mark == MarkSlot.Concrete(TaintMark.ZERO)
        if (p.fact.base != STATIC || p.fact.mark is MarkSlot.Star) return true
        val path = p.fact.path
        return path.size == 1 && path[0].isClass() && p.fact.tail == Tail.EXACT ||
            path.size >= 2 && path[0].isClass() && path[1].isFieldAccessor()
    }

    /** A JVM static anchor is indivisible. A raw array element cannot become a class abstraction. */
    private fun firstFieldEnd(base: AccessPathBase, prefix: List<Int>, path: List<Int>): Int? {
        val index = (prefix.size until path.size).firstOrNull { path[it].isCounted() } ?: return null
        val end = index + 1
        if (base == STATIC && (end < 2 || !path[0].isClass() || !path[1].isFieldAccessor())) return null
        return end
    }
}

package org.opentaint.dataflow.bidi.ap

/** A complete summary pair has one canonical storage key. Point keys stay unchanged. */
data class FlowSummaryForm(val premise: PremiseKey, val facts: Facts)

fun normalizeFlowSummary(manager: ApManager, premise: PremiseKey, facts: Facts): FlowSummaryForm {
    if (!premise.isFlow || facts !is FlowTree) return FlowSummaryForm(premise, facts)
    val initial = premise as InitialAp
    val key = if (initial.tail == Tail.EXACT)
        manager.initial(initial.base, initial.path, Tail.STAR, initial.exclusion, initial.mark)
    else initial
    val result = if (facts.tail == Tail.EXACT)
        manager.flowTree(facts.base, facts.layer, facts.exclusion, facts.markExclusion, facts.root, Tail.STAR)
    else facts
    return FlowSummaryForm(key, result)
}

fun normalizeFlowSummaryConclusion(c: Conclusion): Conclusion =
    if (c.fact.mark is MarkSlot.Star && c.fact.tail == Tail.EXACT)
        c.copy(fact = c.fact.copy(tail = Tail.STAR)) else c

fun assertCanonicalFlowSummary(premise: PremiseKey, facts: Facts) {
    if (!premise.isFlow || facts !is FlowTree) return
    check((premise as InitialAp).tail != Tail.EXACT && facts.tail != Tail.EXACT) {
        "Normalize the complete FLOW pair before summary storage"
    }
}

/** Guidance comparisons use the same pair form as summaries. Raw writer keys stay raw. */
fun normalizeFlowSummaryPatterns(from: Pattern, to: Pattern): Pair<Pattern, Pattern> {
    if (from.fact.mark !is MarkSlot.Star || to.fact.mark !is MarkSlot.Star) return from to to
    fun normal(p: Pattern) = if (p.fact.tail == Tail.EXACT) p.copy(fact = p.fact.copy(tail = Tail.STAR)) else p
    return normal(from) to normal(to)
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.Record

/** AP results only. The owner decides whether to deliver, observe, request or publish them. */
internal interface LocalRelationOut {
    fun data(original: PremiseKey, value: Facts)
    fun target(original: PremiseKey, target: Target)
    fun markRequest(mark: TaintMark)
}

/** One fully matched ND arm. The caller must join every required arm before applying it. */
internal data class LocalRelationBinding(val original: PremiseKey, val initial: InitialAp, val matched: TaintTree)

internal data class NativeRecordLane(val actual: Facts, val pendingDemotion: Boolean)

/** Input was selected with the native record matcher. Real calls retain their action suffix;
 * local boundaries commit pending demotion immediately, but both use these exact input lanes. */
internal fun nativeRecordLanes(ops: ApOps, mode: ApMode, matchedActual: Facts,
                               initial: InitialAp): List<NativeRecordLane> {
    ops.manager.cancellation.checkpoint()
    if (initial.tail != Tail.ANY_TAINT) return listOf(NativeRecordLane(matchedActual, false))
    check(mode.direction == Direction.FORWARD) { "A native must record is only forward" }
    val inside = ops.satisfying(matchedActual, initial, mode)
    val residual = if (inside == null) matchedActual else ops.without(matchedActual, inside)
    return listOfNotNull(inside?.let { NativeRecordLane(it, false) }, residual?.let { NativeRecordLane(it, true) })
}

/** Shared read-only AP transfer for local links and loop observations.
 *
 * This is the relation part of real-call application: no binding stages, alias expansion, rule
 * callbacks, static supplies, current subscriptions or source-hit side effects occur here.
 * The complete parent original is passed to AP composition so cycle protection stays unchanged.
 */
internal class LocalRelationApplication(private val ops: ApOps, private val mode: ApMode) {
    private val ap get() = ops.manager

    fun applyCurrent(actual: Facts, original: PremiseKey, initial: InitialAp,
                     conclusion: Facts, out: LocalRelationOut): Boolean {
        if (!valid(actual, original, initial, conclusion)) return false
        val matched = ops.satisfying(actual, initial, mode) ?: return false
        return applyMatched(matched, original, initial, conclusion, out)
    }

    /** Match once at subscription delivery, then share this exact applicator with saved replay. */
    fun applyMatched(actual: Facts, original: PremiseKey, initial: InitialAp,
                     conclusion: Facts, out: LocalRelationOut): Boolean {
        if (!valid(actual, original, initial, conclusion)) return false
        var applied = false
        ops.applySummary(actual, initial, conclusion, mode,
            sink(original, actual, initial.isZero, pendingDemotion = false, out) { applied = true },
            original = original)
        return applied
    }

    /** Native MUST records have a definite lane and a provisional lane. With no call suffix,
     * commit the existing pending demotion at this boundary rather than after return actions. */
    fun applyRecord(actual: Facts, original: PremiseKey, record: Record, out: LocalRelationOut): Boolean {
        val lanes = matchRecord(actual, original, record) ?: return false
        return applyMatchedRecord(lanes, original, record, out)
    }

    /** A saved native premise is matched once, including its distinct MUST lane split.
     * These invocation-local lanes can be reused for every scalar of this same native row. */
    fun matchRecord(actual: Facts, original: PremiseKey, record: Record): List<NativeRecordLane>? {
        val initial = record.premise
        if (!valid(actual, original, initial, record.conclusion)) return null
        val offered = ops.satisfying(actual, initial, mode, record = true) ?: return null
        return nativeRecordLanes(ops, mode, offered, initial)
    }

    fun applyMatchedRecord(lanes: List<NativeRecordLane>, original: PremiseKey, record: Record,
                           out: LocalRelationOut): Boolean {
        val initial = record.premise
        var applied = false
        for (lane in lanes) {
            if (!valid(lane.actual, original, initial, record.conclusion)) continue
            ops.applySummary(lane.actual, initial, record.conclusion, mode,
                sink(original, lane.actual, initial.isZero, lane.pendingDemotion, out) { applied = true },
                original = original)
        }
        return applied
    }

    /** Opposite-direction records retain the transient native view; do not intern a MUST query. */
    fun applyRecordView(actual: Facts, original: PremiseKey, view: RecordLeafView,
                        nonSubsumable: Boolean, out: LocalRelationOut): Boolean {
        ap.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(original, actual) || !RuntimeDataDomain.base(view.premise.fact.base) ||
            !RuntimeDataDomain.base(view.result.fact.base)) return false
        val matched = ops.satisfying(actual, view.premise, mode, record = true) ?: return false
        var applied = false
        ops.applyRecordLeaf(matched, view, nonSubsumable, mode,
            sink(original, matched, view.premise.fact.base == AccessPathBase.Zero,
                pendingDemotion = false, out) { applied = true }, original = original)
        return applied
    }

    /** Actual execution is AND. Unary metadata is never passed to this complete-join transfer. */
    fun applyCombination(parts: List<LocalRelationBinding>, conclusion: TaintTree, out: LocalRelationOut) {
        require(parts.size >= 2) { "A complete ND relation needs every matched arm" }
        check(mode.direction == Direction.FORWARD && !mode.run1) { "ND summaries require a later forward run" }
        var original: PremiseKey = ap.zero
        val layers = ArrayList<Layer>(parts.size)
        for (part in parts) {
            ap.cancellation.checkpoint()
            check(RuntimeDataDomain.packet(part.original, part.matched))
            original = ap.union(original, part.original)
            layers += part.matched.layer
        }
        val completeOriginal = original
        val triggering = parts.mapNotNull { (it.initial.mark as? MarkSlot.Concrete)?.mark }
            .map { ap.marks.runtimeAtom(it, mode.markMode) }
        val restored = ap.intern(MarkSet(completeOriginal.members.mapNotNull {
            (it.mark as? MarkSlot.Concrete)?.mark?.let { atom -> ap.marks.runtimeAtom(atom, mode.markMode) }
        }.filter { origin -> triggering.any { it != origin } }.map { it.id }.toIntArray()))
        val inherited = parts.any { it.matched.nonSubsumable != null }
        ops.applyMatchedCombination(layers, conclusion, object : ApOut {
            override fun result(f: Facts) {
                val marked = if (inherited && f is TaintTree) f.withProtection(f.root, ap.cancellation) else f
                val result = ap.selectedProtection(marked, restored)
                sink(completeOriginal, conclusion, zeroPremise = false, pendingDemotion = false, out) {}.result(result)
            }
            override fun markRequest(mark: TaintMark) = out.markRequest(mark)
        })
    }

    /** The caller performs the complete ND Target join. The observer can use its selected arm
     * metadata without emitting a Target or replacing the real join by an OR. */
    fun targetArmLayer(actual: Facts, initial: InitialAp, target: Target, saved: Boolean,
                       offeredLayer: Layer = actual.layer): Layer? {
        ap.cancellation.checkpoint()
        if (!RuntimeDataDomain.packet(initial, actual)) return null
        if (mode.direction == Direction.BACKWARD && target is Target.NormalTarget) return null
        val matched = ops.satisfying(actual, initial, mode,
            record = saved && initial.tail != Tail.ANY_TAINT) ?: return null
        val layer = offeredLayer or (matched.layer == Layer.DEMAND)
        return layer.takeIf { target !is Target.NormalTarget || it == Layer.NORMAL }
    }

    private fun valid(actual: Facts, original: PremiseKey, initial: InitialAp, conclusion: Facts): Boolean {
        ap.cancellation.checkpoint()
        return RuntimeDataDomain.packet(original, actual) && RuntimeDataDomain.packet(initial, conclusion)
    }

    private fun sink(original: PremiseKey, actual: Facts, zeroPremise: Boolean,
                     pendingDemotion: Boolean, out: LocalRelationOut,
                     applied: () -> Unit): ApOut = object : ApOut {
        override fun result(f: Facts) {
            if (!RuntimeDataDomain.packet(original, actual) || !RuntimeDataDomain.packet(original, f)) return
            applied()
            fun emit(value: Facts) {
                val committed = if (pendingDemotion) value.withLayer(Layer.DEMAND) else value
                if (mode.direction == Direction.BACKWARD && !zeroPremise && committed is Reach)
                    out.target(original, Target.DemandTarget)
                else out.data(original, committed)
            }
            if (!mode.run1) emit(f) else {
                val runtime = ops.runtimeFact(f, mode)
                var staticOrigin = false
                original.forEachMember { if (it.base == STATIC) staticOrigin = true }
                val demand = runtime.base == STATIC || staticOrigin || runtime is TaintTree && mode.markMode == MarkMode.GROUP
                ops.run1Cover(if (demand) runtime.withLayer(Layer.DEMAND) else runtime, ::emit)
            }
        }
        override fun markRequest(mark: TaintMark) = out.markRequest(mark)
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.interp.ResumeSite
import org.opentaint.dataflow.bidi.driver.ScopedTargetRows
import org.opentaint.dataflow.bidi.store.*
import org.opentaint.dataflow.graph.*
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.ArrayDeque

/** One original method owns all block entries, local links and queued deliveries. */
internal class MethodBlockRuntime(
    private val root: RunMethodAnalyzer,
    private val port: RunnerPort<RunMethodAnalyzer>,
    private val localFactory: MethodLocalServicesFactory,
    private val callFactory: MethodCallServicesFactory,
) : MethodRootRouting {
    private val context = root.context
    private val config = port.config
    private val ap = port.shared.ap
    private val ops = port.shared.ops
    private val mode = config.mode
    private val key = root.key
    private val forward = config.direction == Direction.FORWARD
    private val graph = port.shared.contexts.graph(key, config.direction)
    val layout = port.shared.contexts.blockLayout(key)
    private val directed = layout.directed(graph.graph, backward = !forward)
    private val routesByPort = LinkedHashMap<PortId, MethodBlockRoute>().also { routes ->
        for (from in 0 until graph.graph.size) graph.graph.forEachSuccessor(from) { to ->
            directed.route(from, to).let { routes[it.port] = it }
        }
    }
    private val application = LocalRelationApplication(ops, mode)
    private val restriction = LoopOutputRestriction(ops)
    private val liveLocals = port.shared.contexts.blockLiveLocals(key)
    private val queryCounts = LoopQueryCounts()
    private val localMatchCounts = if (port.shared.n2Statistics != null) LocalSummaryMatchStatistics() else null
    private val savedSelectionCounts = if (port.shared.n2Statistics != null) SavedRecordSelectionStatistics() else null
    private var quantumQueries: LoopQueryScratch? = null
    private var localBoundaryOffers = 0L
    private var localBoundaryDrops = 0L
    private var prePublicationLocalOffers = 0L
    private var prePublicationDeadLocals = 0L
    private val observers = HashMap<Pair<BlockScope, BlockId>, LoopConsumerObservation>()
    private val entries = LinkedHashMap<BlockScope, Entry>()
    private val ready = LinkedHashSet<BlockScope>()
    private val pending = ArrayDeque<() -> Unit>()
    private val staticBoundaryRequests by lazy {
        StaticBoundaryInputRequests(ops, mode, ::forEachLocalInput, ::onRequest)
    }
    private var boundaryLimitOffers = 0L
    private var boundaryLimitCuts = 0L
    private val methodExit = if (forward) PortId.ROOT_EXIT else PortId.ROOT_ENTRY
    private val controlEntry = if (forward) PortId.ROOT_ENTRY else PortId.ROOT_EXIT
    private val exceptionExit = PortId(-4)
    private val normalEndpoints = port.shared.interpreter.exitNodes(key).filter { !it.exceptional }
        .mapTo(HashSet()) { port.shared.language.getInstIndex(it.node) }
    private val exceptionalEndpoints = port.shared.interpreter.exitNodes(key).filter { it.exceptional }
        .mapTo(HashSet()) { port.shared.language.getInstIndex(it.node) }
    private val originalEntry = port.shared.language.getInstIndex(port.shared.interpreter.entryNode(key))
    private val preparedExits = run {
        PreparedExitDirectory(layout, routesByPort, !forward, liveLocals,
            normalEndpoints + exceptionalEndpoints, originalEntry)
    }
    private var released = false

    private data class ChildPoint(val child: BlockId, val exit: PortId)
    private inner class Entry(val scope: BlockScope, val rootEntry: Boolean = false) {
        var stateOrNull: BlockRunState? = null
        val state: BlockRunState get() = checkNotNull(stateOrNull) { "A saved-only offer has no mutable block state" }
        val starts = LinkedHashSet<Int>()
        val methodStarts = LinkedHashSet<Int>()
        val requests = RequestStorage()
        val completions = LinkedHashMap<ChildPoint, ScopedEdgeStore<ChildPoint>>()
        var borrowedExceptionalNormalZero = false
        val demand: BlockBoundaryDemandView? = if (rootEntry || config.run1) null else {
            val store = checkNotNull(config.demand)
            BlockBoundaryDemandView(ap, store.scope(key, scope),
                store.scope(key, BlockScope(scope.block, controlEntry)), config.direction,
                entryRole(scope), normalOutputs(scope)) { output, original, policy ->
                store.acceptsStaticShortcutTarget(key, scope.block, output, original, policy)
            }
        }
        private val cacheValue = lazy {
            if (layout[scope.block].instructions.isEmpty()) null else
                BlockCfgDeliveryCache(layout, graph.graph, scope.block, !forward, ap.cancellation,
                    directedView = directed) { index, base ->
                    val node = graph.instructions[index]
                    context.isEnd(node) || context.isExceptionalExit(node) || context.forms.isBaseRelevant(key, node, base)
                }
        }
        val cache: BlockCfgDeliveryCache? get() = cacheValue.value
        fun existingCache(): BlockCfgDeliveryCache? = if (cacheValue.isInitialized()) cacheValue.value else null
        fun ensureState(): BlockRunState {
            stateOrNull?.let { return it }
            return BlockRunState(key, port,
                PublicationSink { _, _ -> error("An internal block cannot publish externally") },
                localFactory, callFactory,
                TargetPublicationSink { _, _ -> error("An internal block cannot publish external Targets") }, Binding(this))
                .also { stateOrNull = it }
        }
        val links = BlockSummaryLinks(ops, mode, scope, ::onData, ::onTerminal, ::onRequest, localMatchCounts)
        fun addCompletion(child: BlockId, exit: PortId, original: PremiseKey, value: Facts): Facts? {
            val point = ChildPoint(child, exit)
            val store = completions.getOrPut(point) {
                val directory = object : PointDirectory<ChildPoint> {
                    override val size = 1
                    override fun index(point: ChildPoint): Int {
                        check(point == childPoint) { "A child completion belongs to its exact point" }
                        return 0
                    }
                    private val childPoint = point
                }
                ScopedEdgeStore(ap, directory, config.fieldLimit,
                    flowBacked = mode.run1 && mode.markMode == MarkMode.FULL,
                    collectStatistics = port.shared.n2Statistics != null)
            }
            return store.add(point, original, value)
        }
    }

    init {
        check(layout.hasLoops) { "A loop-free method keeps its existing root path" }
        entries[BlockScope.ROOT] = Entry(BlockScope.ROOT, rootEntry = true).also { it.stateOrNull = root }
    }

    fun states(): List<Pair<BlockScope, BlockRunState>> = entries.mapNotNull { (scope, e) -> e.stateOrNull?.let { scope to it } }
    fun state(scope: BlockScope): BlockRunState = entries[scope]?.state ?: error("Unentered block scope $scope")
    fun scheduleRoot() { ready += BlockScope.ROOT }
    fun requireIdle() {
        check(quantumQueries == null) { "An active observer quantum cannot be sealed" }
        check(ready.isEmpty() && pending.isEmpty() && entries.values.none { it.links.hasPending || it.stateOrNull?.hasLocalWork == true }) {
            "A method has pending block work"
        }
    }

    override fun start(node: CommonInst, original: InitialAp, value: Facts) {
        check(!released)
        if (!forward && port.shared.language.getInstIndex(node) in exceptionalEndpoints) {
            // Selected HACK: the already admitted original ZERO follows the
            // real exceptional boundary and its actual discovery successors.
            root.startAt(original, node, value) { pr, result -> root.enqueueInput(node, pr, result) }
        } else routeInside(entries.getValue(BlockScope.ROOT), port.shared.language.getInstIndex(node),
            original, value, controlEntry, methodStart = true)
    }

    override fun enter(node: CommonInst, original: PremiseKey, value: Facts) = enterRoot(node, original, value)
    override fun intersectSummary(exit: PortId, original: PremiseKey, raw: Facts): List<Facts>? =
        if (quantumQueries == null) null else intersect(entries.getValue(BlockScope.ROOT), exit, original, raw)
    fun enterRoot(node: CommonInst, original: PremiseKey, value: Facts) {
        check(!released)
        if (!forward && port.shared.language.getInstIndex(node) in exceptionalEndpoints)
            root.enqueueInput(node, original, value)
        else routeInside(entries.getValue(BlockScope.ROOT), port.shared.language.getInstIndex(node), original, value, controlEntry)
    }
    override fun successors(node: CommonInst, original: PremiseKey, value: Facts) = successorsRoot(node, original, value)
    fun successorsRoot(node: CommonInst, original: PremiseKey, value: Facts) {
        val from = port.shared.language.getInstIndex(node)
        graph.forEachSuccessor(port.shared.language, node) { next ->
            val to = port.shared.language.getInstIndex(next)
            routeInside(entries.getValue(BlockScope.ROOT), to, original, value, directed.route(from, to).port)
        }
    }

    /** Call only on the method owner while its counted work reservation is held. */
    fun work(quantum: Int): Boolean {
        check(quantumQueries == null)
        quantumQueries = LoopQueryScratch(ap, queryCounts)
        return try { workQuantum(quantum) } finally {
            quantumQueries?.clear()
            quantumQueries = null
        }
    }

    private fun workQuantum(quantum: Int): Boolean {
        require(quantum > 0)
        var used = 0
        while (used < quantum) {
            ap.cancellation.checkpoint()
            if (pending.isNotEmpty()) { pending.removeFirst().invoke(); used++; continue }
            val delivery = entries.values.firstOrNull { it.links.hasPending }
            if (delivery != null) { used += delivery.links.drain(1); continue }
            val selected = ready.firstOrNull { entries.getValue(it).state.localHasZeroWork }
                ?: if (mode.run1 && mode.markMode == MarkMode.FULL)
                    ready.firstOrNull { entries.getValue(it).state.localHasFlowWork } ?: ready.firstOrNull()
                else ready.firstOrNull()
            if (selected == null) return true
            ready.remove(selected)
            val state = entries.getValue(selected).state
            if (!state.workLocal(1)) ready += selected
            used++
        }
        return ready.isEmpty() && pending.isEmpty() && entries.values.none { it.links.hasPending || it.stateOrNull?.hasLocalWork == true }
    }

    private fun entry(scope: BlockScope): Entry = entries.getOrPut(scope) { Entry(scope) }

    private fun admitTarget(e: Entry, target: Int, original: PremiseKey, value: Facts): Boolean {
        if (target in e.starts) return false
        val normal = layout.normalExit(e.scope.entry)
        if (normal != null) {
            check(if (forward) target == normal.target else normal.routes.any { directedRoute(it).to == target }) {
                "A canonical normal interface keeps its certified real targets"
            }
        } else if (e.scope.entry.ordinal >= 0)
            check(directedRoute(e.scope.entry).to == target) { "A physical entry port has one actual target" }
        if (e.starts.isNotEmpty()) {
            check(normal != null || e.scope.entry.ordinal < 0 && original.isZero && value is Reach &&
                e.stateOrNull?.initials?.all().orEmpty().all { it.isZero }) {
                "Distinct logical control targets cannot share ordinary DATA initials"
            }
        }
        e.starts += target
        return true
    }

    private fun queue(action: () -> Unit) {
        pending += action
        port.enqueue(root)
    }

    private inner class Binding(private val e: Entry) : BlockRuntimeBinding {
        override val scope get() = e.scope
        override val context get() = this@MethodBlockRuntime.context
        override val points = object : PointDirectory<CommonInst> {
            override val size get() = layout[e.scope.block].instructions.size
            override fun index(point: CommonInst): Int {
                val index = port.shared.language.getInstIndex(point)
                check(layout.ownerOf(index) == e.scope.block)
                return layout.localIndex(index)
            }
        }
        override val bodyWork get() = root.sharedBodyWork
        override val sourceHits get() = root.sourceHits
        override val sinkSeeds get() = root.sinkSeeds
        override val demand get() = e.demand
        override fun intersectSummary(exit: PortId, original: PremiseKey, raw: Facts): List<Facts>? =
            if (quantumQueries == null) null else intersect(e, exit, original, raw)
        override fun keepLocalConclusion(exit: PortId, value: Facts): Boolean =
            this@MethodBlockRuntime.keepLocalConclusion(e.scope.block, exit, value)
        override fun prepareExit(exit: PortId, base: org.opentaint.dataflow.ap.ifds.AccessPathBase): PreparedExit {
            val prepared = preparedExits.getOrPrepare(e.scope, exit, base)
            if (base is org.opentaint.dataflow.ap.ifds.AccessPathBase.LocalVar) {
                prePublicationLocalOffers++
                if (prepared === PreparedExit.DeadData) prePublicationDeadLocals++
            }
            return prepared
        }
        override fun schedule() { ready += scope; port.enqueue(root) }
        override fun start(state: BlockRunState, original: InitialAp, value: Facts) {
            check(original.isZero || e.starts.size <= 1 || layout.normalExit(scope.entry) != null) { "A DATA initial has one exact entry target" }
            if (isEmptyBlock(scope.block)) {
                val start = e.starts.singleOrNull()
                if (start != null && start in e.methodStarts)
                    state.startAt(original, graph.instructions[start], value)
                else state.retainBlockSummary(scope.entry, original, value)
                return
            }
            for (target in e.starts.toList()) queue { startEntryTarget(e, state, target, original, value) }
        }
        override fun startResult(state: BlockRunState, node: CommonInst, original: PremiseKey, value: Facts) {
            if (isEmptyBlock(scope.block)) state.retainBlockSummary(scope.entry, original, value)
            else routeInside(e, port.shared.language.getInstIndex(node), original, value, scope.entry)
        }
        override fun successors(state: BlockRunState, node: CommonInst, original: PremiseKey, value: Facts) {
            val from = port.shared.language.getInstIndex(node)
            for (next in checkNotNull(e.cache).after(from, value.base)) dispatch(e, next, original, value)
        }
        override fun publish(state: BlockRunState, exit: PortId, publications: List<Publication>) {
            e.links.publish(exit, publications)
            port.enqueue(root)
        }
        override fun publishTargets(state: BlockRunState, targets: TargetBatch) {
            e.links.publishTargets(targets)
            port.enqueue(root)
        }
        override fun borrowRequests(input: Facts) = e.requests.borrowMatchingRows(input, ap.cancellation::checkpoint)
        override fun borrowRequest(slot: Run1Slot) = e.requests.borrow(slot)
        override fun commitRequests(state: BlockRunState, temporary: RequestStorage) {
            val fresh = LinkedHashMap<Run1Slot, RequestMarkSet>()
            for ((slot, marks) in temporary.pendingRows()) {
                val delta = e.requests.addAll(slot, marks, ap.cancellation::checkpoint)
                if (!delta.isEmpty) fresh[slot] = delta
            }
            if (fresh.isEmpty()) return
            e.links.forEachInput { link, value -> applyRequests(e, link, value, fresh) }
        }
        override fun staticMarkRequest(initial: InitialAp, mark: TaintMark) {
            if (config.run1 && forward && scope.entry == PortId.ROOT_EXIT)
                staticBoundaryRequests.request(scope, initial, mark)
        }
        override fun staticTicket(): Long = root.allocateStaticTicket(scope)
        override fun routeStaticToExit(state: BlockRunState, node: CommonInst, original: PremiseKey, value: Facts) {
            state.retainBlockSummary(PortId.STATIC_SHORTCUT, original, value)
        }
        override fun methodBoundary(state: BlockRunState, node: CommonInst, original: PremiseKey, value: Facts, summary: Boolean) {
            state.endAt(original, node, value, summary)
        }
        override fun deliveryStatistics(): BlockDeliveryStatistics? = e.existingCache()?.let {
            BlockDeliveryStatistics(it.hits, it.searches, it.visitedNodes, it.destinations, it.maxWidth)
        }
    }

    private fun startEntryTarget(e: Entry, state: BlockRunState, target: Int, original: PremiseKey, value: Facts) {
        if (isEmptyBlock(e.scope.block)) {
            // A shared normal interface can discover another real reverse
            // predecessor after this identity region already admitted its
            // initial. Replay the same logical identity as Binding.start;
            // the physical predecessor belongs to the adjacent region.
            if (target in e.methodStarts) state.startAt(original, graph.instructions[target], value)
            else state.retainBlockSummary(e.scope.entry, original, value)
        } else if (target in e.methodStarts && layout[e.scope.block].isLeaf)
            state.startAt(original, graph.instructions[target], value)
        else routeInside(e, target, original, value, e.scope.entry, methodStart = target in e.methodStarts)
    }

    private fun routeInside(parent: Entry, target: Int, original: PremiseKey, value: Facts,
                            arrival: PortId, passedEmpty: Boolean = false, methodStart: Boolean = false) {
        ap.cancellation.checkpoint()
        val block = layout[parent.scope.block]
        if (block.isLeaf) {
            check(layout.ownerOf(target) == block.id)
            for (next in checkNotNull(parent.cache).targets(target, value.base)) dispatch(parent, next, original, value)
            return
        }
        val next = block.children.single { layout.contains(it, target) }
        val emptyPrefix = if (forward) block.before else block.after
        val arrivalRoute = routesByPort[arrival]
        if (!passedEmpty && next == block.loop && emptyPrefix != null &&
            isEmptyBlock(emptyPrefix) && arrivalRoute?.feedbackLoop != next && arrivalRoute?.discovery != true) {
            offerChild(parent, emptyPrefix, target, original, value, arrival, methodStart)
        } else offerChild(parent, next, target, original, value, arrival, methodStart)
    }

    private fun dispatch(e: Entry, target: BlockDeliveryTarget, original: PremiseKey, value: Facts) {
        when (target) {
            is BlockDeliveryTarget.Statement -> e.state.enqueueInput(graph.instructions[target.index], original, value)
            is BlockDeliveryTarget.Boundary -> e.state.retainBlockSummary(outputPort(target.route.port, e.scope.block), original, value)
        }
    }

    private fun offerChild(parent: Entry, child: BlockId, target: Int, original: PremiseKey, value: Facts, arrival: PortId,
                           methodStart: Boolean = false) {
        // DATA/native rows keep the actual ingress, including ZERO identity
        // relations. A typed terminal endpoint is not a replacement for it.
        val logical = inputPort(arrival, parent.scope.block, child)
        val scope = BlockScope(child, logical)
        val childEntry = entry(scope)
        if (methodStart) childEntry.methodStarts += target
        val link = LocalLink(parent.scope, logical, original, value.layer, scope)
        if (LoopPipelineTrace.enabled(config.index, key)) LoopPipelineTrace.record(config.index, key, "local-offer") {
            catalog(ap); text("parent", parent.scope.toString()); text("child", scope.toString())
            number("point", logical.ordinal); number("target", target)
            premise("P", original); facts("offered", value)
        }
        replaySaved(childEntry, link, value)
        val admission = if (config.run1) null else childEntry.demand!!.admission(value, config.admissionPolicy)
        val initials = admission?.initials
        if (initials != null && initials.isEmpty()) return
        if (admission?.borrowedExceptionalNormalZero == true) childEntry.borrowedExceptionalNormalZero = true
        val state = childEntry.ensureState()
        val admittedTarget = admitTarget(childEntry, target, original, value)
        if (admittedTarget && layout.normalExit(scope.entry) != null) {
            // All these targets are true reverse predecessors of the SAME
            // original normal join. A previously admitted fact reaches each.
            for (initial in state.initials.admissions()) {
                val intrinsic = ops.startFact(initial.initial, mode)
                val start = state.forceRun1Layer(initial.initial,
                    intrinsic.withLayer(intrinsic.layer or (initial.layer == Layer.DEMAND)))
                queue { startEntryTarget(childEntry, state, target, initial.initial, start) }
            }
        } else if (admittedTarget && state.initials.all().any { it.isZero } && original.isZero && value is Reach)
            queue { startEntryTarget(childEntry, state, target, ap.zero, state.forceRun1Layer(ap.zero, ops.startFact(ap.zero, mode))) }
        childEntry.links.offer(link, value)
        if (childEntry.links.hasPending) port.enqueue(root)
        if (config.run1) {
            checkNotNull(state.abstraction).emit(original, value)
            if (value is FlowTree) applyRequests(childEntry, link, value, childEntry.requests.pendingRows())
        } else for (initial in checkNotNull(initials)) state.addInitial(initial)
    }

    fun offerStaticAnswer(link: LocalLink, original: InitialAp, value: Facts) {
        val child = entries.getValue(link.child)
        val selected = link.copy(original = original, layer = value.layer)
        replaySaved(child, selected, value)
        child.links.offer(selected, value)
        // This callback can run in a StaticOwner event while the method is
        // idle. A fresh link can queue current-summary deliveries even when
        // abstraction.emit finds only initials which already exist. Keep a
        // counted method Work reservation for those deliveries independently
        // of initial admission.
        if (child.links.hasPending) port.enqueue(root)
        if (forward && child.scope.entry == PortId.ROOT_EXIT && value.base == STATIC) {
            // The selected outer link retains CF/T -> CG/T. The local span's
            // own initial is CG/T; propagate this real supplied operation input
            // through the same identity continuations used by the raw write.
            for (scalar in annotatedLoopScalars(ops, value)) {
                val initial = concreteStaticResumeInitial(ap, ops.leaves(scalar).single())
                routeStaticBoundaryInput(child, initial, scalar)
            }
        } else checkNotNull(child.state.abstraction).emit(original, value)
    }

    private fun applyRequests(child: Entry, link: LocalLink, actual: Facts, rows: RequestRows) {
        if (actual is TaintTree) {
            checkNotNull(child.state.abstraction).emit(link.original, actual)
            return
        }
        if (actual !is FlowTree || !link.original.isFlow) return
        for ((slot, marks) in rows) {
            if (!slotMatches(slot, actual)) continue
            val cursor = marks.cursor()
            while (!cursor.isComplete) cursor.step(256) { mark -> onRequest(link, actual, mark) }
        }
    }

    private fun onRequest(link: LocalLink, actual: Facts, mark: TaintMark) {
        if (!config.run1 || actual !is FlowTree) return
        val original = link.original as? InitialAp ?: return
        if (original.mark !is MarkSlot.Star) return
        if (original.base == STATIC) root.requestLocalStaticInput(link, actual, mark)
        else entries.getValue(link.parent).state.addMarkRequest(original, mark)
    }

    private fun savedRows(scope: BlockScope, actual: Facts): Sequence<SavedRecordSelection> =
        selectSavedRecords(config.records, key, scope, actual, ops, config.direction, savedSelectionCounts).asSequence()

    private fun replaySaved(child: Entry, link: LocalLink, actual: Facts) {
        for (selected in savedRows(child.scope, actual)) {
            val record = selected.record
            val exit = checkNotNull(record.exitIn(config.direction))
            if (record.direction == config.direction) {
                preparedExits.getOrPrepare(child.scope, if (isEmptyBlock(child.scope.block)) child.scope.entry else exit,
                    record.conclusion.base)
                savedSelectionCounts?.let { it.replayDirectMatches++ }
                val lanes = application.matchRecord(actual, link.original, record) ?: continue
                for (scalar in annotatedLoopScalars(ops, record.conclusion)) {
                    val row = Record(key, record.direction, record.premise, scalar)
                    applySaved(child, link, actual, exit, record.premise, ops.leaves(scalar).single()) {
                        out -> application.applyMatchedRecord(lanes, link.original, row, out)
                    }
                }
            } else {
                selected.forEachReversedAt(actual, ops) { view, protected ->
                    applySavedView(child, link, actual, exit, view, protected)
                }
            }
        }
        for ((row, member) in config.normalTargets.candidates(key, child.scope, link.original, actual, mode))
            child.links.replaySavedTarget(link, actual, row, member)
        if (child.links.hasPending) port.enqueue(root)
    }

    private fun applySaved(child: Entry, link: LocalLink, actual: Facts, exit: PortId,
                           row: PremiseKey, geometry: Pattern, apply: (LocalRelationOut) -> Unit) {
        apply(object : LocalRelationOut {
            override fun data(original: PremiseKey, value: Facts) = onData(link, exit, row, geometry, original, value)
            override fun target(original: PremiseKey, target: Target) = onTerminal(link, original, target)
            override fun markRequest(mark: TaintMark) = onRequest(link, actual, mark)
        })
    }

    private fun applySavedView(child: Entry, link: LocalLink, actual: Facts, exit: PortId,
                               view: RecordLeafView, protected: Boolean) {
        preparedExits.getOrPrepare(child.scope, if (isEmptyBlock(child.scope.block)) child.scope.entry else exit, view.result.fact.base)
        if (LoopPipelineTrace.enabled(config.index, key)) LoopPipelineTrace.record(config.index, key, "local-reversed-record") {
            catalog(ap); text("parent", link.parent.toString()); text("child", link.child.toString())
            number("exit", exit.ordinal); number("point", link.point.ordinal)
            premise("P", link.original); facts("offered", actual)
            pattern("I", view.premise); pattern("O", Pattern(view.result.fact, view.result.exclusion))
            flag("resultDemand", view.result.demand); flag("protected", protected)
        }
        val grows = loopFieldLength(Pattern(view.result.fact, view.result.exclusion)) > loopFieldLength(view.premise)
        application.applyRecordView(actual, link.original, view, protected, object : LocalRelationOut {
            override fun data(original: PremiseKey, value: Facts) = onApplied(link, exit, grows, original, value)
            override fun target(original: PremiseKey, target: Target) = onTerminal(link, original, target)
            override fun markRequest(mark: TaintMark) = onRequest(link, actual, mark)
        })
    }

    private fun onData(link: LocalLink, exit: PortId, row: PremiseKey, geometry: Pattern,
                       original: PremiseKey, value: Facts) {
        if (LoopPipelineTrace.enabled(config.index, key)) LoopPipelineTrace.record(config.index, key, "local-relation") {
            catalog(ap); text("parent", link.parent.toString()); text("child", link.child.toString())
            number("exit", exit.ordinal); number("point", link.point.ordinal)
            premise("I", row); pattern("O", geometry); premise("P", original); facts("applied", value)
        }
        onApplied(link, exit, loopSummaryGrows(row, geometry), original, value)
    }

    private fun onApplied(link: LocalLink, exit: PortId, grows: Boolean, original: PremiseKey, value: Facts) {
        val parent = entries.getValue(link.parent)
        val child = layout[link.child.block]
        val completionExit = if (isEmptyBlock(child.id)) link.point else exit
        val routes = preparedExits.getOrPrepare(link.child, completionExit, value.base)
        if (LoopPipelineTrace.enabled(config.index, key)) LoopPipelineTrace.record(config.index, key, "local-applied") {
            catalog(ap); text("parent", link.parent.toString()); text("child", link.child.toString())
            number("exit", exit.ordinal); number("point", completionExit.ordinal)
            premise("P", original); facts("value", value); flag("grows", grows)
            text("prepared", routes.javaClass.simpleName)
        }
        if (routes === PreparedExit.DeadData) return
        // Reuse the ordinary global AP bound before a local result is stored
        // or offered onward. A saved relation can add its own prefix to the
        // caller suffix, just as a real call summary does. This is not a new
        // loop cut and does not invoke a physical instruction/rule cut hook.
        boundaryLimitOffers++
        val depth = when (value) {
            is Reach -> 0
            is FlowTree -> value.root.boundedDepth
            is TaintTree -> value.root.boundedDepth
        }
        if (depth > config.fieldLimit) boundaryLimitCuts++
        ops.limit(value, config.fieldLimit, object : ApOut {
            override fun result(bounded: Facts) {
                val values = if (!child.isLoop || exit.ordinal < 0) listOf(bounded) else
                    restriction.restrict(config.run1, grows, bounded, LoopRestrictionSession(ops, config.admissionPolicy,
                        { candidate -> observe(parent, child, link, exit, original, candidate) },
                        { actual -> observers[parent.scope to child.id]?.precisionCursors(actual) }))
                for (kept in values) {
                    if (LoopPipelineTrace.enabled(config.index, key)) LoopPipelineTrace.record(config.index, key, "local-kept") {
                        catalog(ap); text("parent", link.parent.toString()); text("child", link.child.toString())
                        number("exit", exit.ordinal); number("point", completionExit.ordinal)
                        premise("P", original); facts("kept", kept)
                    }
                    val fresh = parent.addCompletion(child.id, completionExit, original, kept)
                    if (LoopPipelineTrace.enabled(config.index, key)) LoopPipelineTrace.record(config.index, key, "local-completion") {
                        catalog(ap); text("parent", link.parent.toString()); text("child", link.child.toString())
                        number("exit", exit.ordinal); number("point", completionExit.ordinal)
                        premise("P", original); facts("offered", kept); flag("fresh", fresh != null)
                        if (fresh != null) facts("delta", fresh)
                    }
                    if (fresh == null) continue
                    queue { routeCompleted(parent, child, link, exit, original, fresh, routes) }
                }
            }
            override fun markRequest(mark: TaintMark) = error("A global local-boundary field limit cannot request a mark")
        })
    }

    private fun onTerminal(link: LocalLink, original: PremiseKey, target: Target) {
        queue { entries.getValue(link.parent).state.emitTarget(original, target) }
    }

    private fun routeCompleted(parent: Entry, child: MethodBlock, link: LocalLink, exit: PortId,
                               original: PremiseKey, value: Facts, prepared: PreparedExit) {
        if (isEmptyBlock(child.id)) {
            if (link.point.ordinal >= 0) for (route in preparedRoutes(prepared, link.point)) {
                if (route.feedbackLoop == parent.scope.block)
                    parent.state.retainBlockSummary(route.port, original, value)
                else if (layout.contains(parent.scope.block, route.to))
                    routeInside(parent, route.to, original, value, link.point, passedEmpty = true)
                else parent.state.retainBlockSummary(outputPort(route.port, parent.scope.block), original, value)
            } else for (target in entries.getValue(link.child).starts.toList()) {
                if (prepared is PreparedExit.ActualStarts && !prepared.allows(target)) continue
                if (layout.contains(parent.scope.block, target))
                    routeInside(parent, target, original, value, link.point, passedEmpty = true)
                else parent.state.retainBlockSummary(link.point, original, value)
            }
            return
        }
        if (exit == PortId.STATIC_SHORTCUT) {
            check(config.run1 && forward && value.base == STATIC) {
                "Only an unprocessed run-1 static output uses the shortcut channel"
            }
            if (parent.scope == BlockScope.ROOT) routeStaticBoundaryInput(parent, original, value)
            else parent.state.retainBlockSummary(PortId.STATIC_SHORTCUT, original, value)
            return
        }
        if (exit.ordinal < 0) {
            if (parent.scope == BlockScope.ROOT) {
                val node = if (exit == exceptionExit) port.shared.interpreter.exitNodes(key).single { it.exceptional }.node
                    else if (forward) context.normalExit else port.shared.interpreter.entryNode(key)
                // ROOT_EXIT comes from an actual completed handler, whether
                // its input used normal J or the private operation continuation.
                root.finishBoundMethodBoundary(original, node, value, summary = exit != exceptionExit)
            } else parent.state.retainBlockSummary(exit, original, value)
            return
        }
        for (route in preparedRoutes(prepared, exit)) {
            if (layout.contains(parent.scope.block, route.to) && route.feedbackLoop != parent.scope.block)
                routeInside(parent, route.to, original, value, exit)
            else if (parent.scope == BlockScope.ROOT) error("An original CFG edge cannot leave its method layout")
            else {
                val suffixId = if (forward) layout[parent.scope.block].after else layout[parent.scope.block].before
                val suffix = suffixId?.let { layout[it] }
                if (suffix != null && isEmptyBlock(suffix.id) && child.id != suffix.id)
                    offerChild(parent, suffix.id, route.to, original, value, exit)
                else parent.state.retainBlockSummary(outputPort(route.port, parent.scope.block), original, value)
            }
        }
    }

    private fun preparedRoutes(prepared: PreparedExit, exit: PortId): List<MethodBlockRoute> = when (prepared) {
        is PreparedExit.Routes -> prepared.routes
        PreparedExit.DeadData -> emptyList()
        else -> deliveryRoutes(exit) // Unknown interfaces keep their established native dispatch.
    }

    private fun entryRole(scope: BlockScope): BlockEntryRole {
        if (layout.normalExit(scope.entry) != null) return BlockEntryRole.NORMAL_INTERFACE
        val route = routesByPort[scope.entry] ?: return BlockEntryRole.MID_BLOCK
        if (route.discovery || !forward && route.from in exceptionalEndpoints || forward && route.to in exceptionalEndpoints)
            return BlockEntryRole.EXCEPTIONAL_INTERFACE
        val crossesNormalInterface = !layout.contains(scope.block, route.from) && layout.contains(scope.block, route.to) ||
            route.feedbackLoop == scope.block || isEmptyBlock(scope.block)
        val actualRootNormal = if (forward) route.from == originalEntry else route.from in normalEndpoints
        return if (crossesNormalInterface || actualRootNormal) BlockEntryRole.NORMAL_INTERFACE else BlockEntryRole.MID_BLOCK
    }

    private fun normalOutputs(scope: BlockScope): Set<PortId> = buildSet {
        if (isEmptyBlock(scope.block)) {
            if (scope.entry in routesByPort || layout.normalExit(scope.entry) != null) add(scope.entry)
            return@buildSet
        }
        for (route in routesByPort.values) {
            if (route.discovery || forward && route.to in exceptionalEndpoints) continue
            if (layout.contains(scope.block, route.from) &&
                (!layout.contains(scope.block, route.to) || route.feedbackLoop == scope.block || isRootEnd(route.to)))
                add(outputPort(route.port, scope.block))
        }
    }

    private fun isRootEnd(index: Int): Boolean = graph.instructions[index].let {
        context.isEnd(it) || context.isExceptionalExit(it)
    }

    /** An empty prefix still has a genuine identity/rule interface. Physical endpoints own transfers. */
    private fun isEmptyBlock(block: BlockId): Boolean = layout[block].let {
        it.isLeaf && !it.isLoop && it.instructions.isEmpty()
    }

    /** Continue a real run-1 write shortcut at its original normal-exit operation.
     * ROOT_EXIT is the selected operation-local static continuation address, not
     * a method-entry seed. Its local rows therefore include the real exit rules.
     */
    private fun routeStaticBoundaryInput(parent: Entry, original: PremiseKey, value: Facts) {
        check(config.run1 && forward && value.base == STATIC)
        val target = port.shared.language.getInstIndex(context.normalExit)
        val block = layout[parent.scope.block]
        if (block.isLeaf) {
            for (scalar in annotatedLoopScalars(ops, value)) {
                val leaf = ops.leaves(scalar).single()
                val initial = if (value is TaintTree) concreteStaticResumeInitial(ap, leaf) else {
                    check(leaf.fact.path.size >= 2) { "A static FLOW continuation names a field" }
                    ap.initial(Pattern(leaf.fact.copy(path = leaf.fact.path.take(2),
                        tail = Tail.STAR, mark = MarkSlot.STAR), ExclusionSet.Empty))
                }
                parent.state.installPoint(initial, scalar,
                    ResumeSite.BoundaryInput(parent.state.operation(context.normalExit), atStart = false), null)
            }
            return
        }
        val childId = block.children.single { layout.contains(it, target) }
        val child = entry(BlockScope(childId, PortId.ROOT_EXIT))
        val link = LocalLink(parent.scope, PortId.ROOT_EXIT, original, value.layer, child.scope)
        replaySaved(child, link, value)
        child.ensureState()
        admitTarget(child, target, original, value)
        child.links.offer(link, value)
        if (child.links.hasPending) port.enqueue(root)
        // A local operation input keeps its own initial, exactly as an existing
        // physical static-read reply. It does not enter Run1Abstraction.
        for (scalar in annotatedLoopScalars(ops, value)) {
            val leaf = ops.leaves(scalar).single()
            val initial = if (value is TaintTree) concreteStaticResumeInitial(ap, leaf) else
                ap.initial(Pattern(leaf.fact.copy(path = leaf.fact.path.take(2),
                    tail = Tail.STAR, mark = MarkSlot.STAR), ExclusionSet.Empty))
            routeStaticBoundaryInput(child, initial, scalar)
        }
    }

    /** Only the interface currently being crossed changes the port view.
     * An inner normal completion can retain an enclosing loop's repeat role.
     */
    private fun outputPort(actual: PortId, block: BlockId): PortId =
        layout.normalExitsForRoute(actual).filter { normal ->
            val adjacent = layout[normal.loop].parent?.let { layout[it].after }
            layout.isAncestor(normal.loop, block) || adjacent?.let { layout.isAncestor(it, block) } == true
        }.maxByOrNull { layout[it.loop].depth }?.id ?: actual

    private fun inputPort(actual: PortId, parent: BlockId, child: BlockId): PortId {
        if (layout.normalExit(actual) != null) return actual
        return layout.normalExitsForRoute(actual).filter { normal ->
            layout.isAncestor(normal.loop, child) ||
                layout[normal.loop].parent == parent && layout[parent].after == child
        }.maxByOrNull { layout[it.loop].depth }?.id ?: actual
    }

    /** Same actual output adapter for live delivery and the pure paired observer. */
    private fun enclosingPorts(exit: PortId, parent: BlockId): List<PortId> =
        if (exit.ordinal < 0) listOf(exit) else deliveryRoutes(exit)
            .map { outputPort(it.port, parent) }.distinct()

    /** Forward has one certified target; reverse restores EVERY real predecessor. */
    private fun deliveryRoutes(portId: PortId): List<MethodBlockRoute> =
        layout.normalExit(portId)?.routes?.map(::directedRoute) ?: listOf(directedRoute(portId))

    private fun directedRoute(portId: PortId): MethodBlockRoute =
        routesByPort[portId] ?: error("Unknown directed block port $portId")

    private fun keepAlongRoute(route: MethodBlockRoute, value: Facts, count: Boolean = true): Boolean {
        val local = value.base as? org.opentaint.dataflow.ap.ifds.AccessPathBase.LocalVar ?: return true
        if (count) localBoundaryOffers++
        // The actual endpoint handler must run before filtering its completed DATA.
        val keep = isRootEnd(route.to) || route.to == originalEntry ||
            liveLocals?.mayFollow(!forward, route, local.idx) != false
        if (!keep && count) localBoundaryDrops++
        return keep
    }

    private fun keepLocalConclusion(block: BlockId, exit: PortId, value: Facts, count: Boolean = true): Boolean {
        if (value.base !is org.opentaint.dataflow.ap.ifds.AccessPathBase.LocalVar) return true
        if (count) localBoundaryOffers++
        // Synthetic/unknown interfaces retain the native path until a real
        // continuation is available. A missing mask is not an empty mask.
        if (exit.ordinal < 0 || liveLocals == null) return true
        val normal = layout.normalExit(exit)
        if (normal == null && exit !in routesByPort) return true
        val keep = deliveryRoutes(exit).any { keepAlongRoute(it, value, count = false) }
        if (!keep && count) localBoundaryDrops++
        return keep
    }

    private fun plan(parent: Entry, exit: PortId, original: PremiseKey, templates: List<Pattern>): PreparedLocalDataPlan? {
        val scratch = quantumQueries ?: return null
        val view: Any = if (parent.rootEntry) checkNotNull(config.demand) else checkNotNull(parent.demand)
        return scratch.plan(view, exit, original, templates, config.admissionPolicy) {
            if (parent.rootEntry) checkNotNull(config.demand).prepareDataPlan(key, templates, config.admissionPolicy) { queryCounts.planChecks++ }
            else (parent.demand as? PreparedScopeDemandView)?.prepareDataPlan(exit, templates, config.admissionPolicy) { queryCounts.planChecks++ }
        }
    }

    private fun intersect(parent: Entry, exit: PortId, original: PremiseKey, value: Facts): List<Facts> {
        if (value !is Reach && !original.isZero && original.size <= 2048) {
            val prepared = plan(parent, exit, original, original.members.map { it.toPattern() })
            if (prepared != null) {
                prepared.intersect(original, value)?.let { queryCounts.c5PreparedQueries++; return it }
                queryCounts.c5ReferenceFallbacks++
            }
        }
        queryCounts.c5NativeQueries++
        return if (parent.rootEntry) checkNotNull(config.demand).intersect(key, original, value, config.admissionPolicy)
            else checkNotNull(parent.demand).intersect(exit, original, value, config.admissionPolicy)
    }

    private fun skipEmptyDataReplay(parent: Entry, original: PremiseKey, actual: Facts,
                                    saved: LoopObservedRecord): Boolean {
        val record = saved.record
        if (parent.rootEntry || mode.run1 || original.isZero || original.size > 2048 || actual is Reach ||
            original.isFlow != (actual is FlowTree) || record.direction != config.direction ||
            record.premise.isZero || record.premise.tail == Tail.ANY_TAINT || record.conclusion is Reach ||
            record.conclusion.base == org.opentaint.dataflow.ap.ifds.AccessPathBase.Zero ||
            record.premise.isFlow != (record.conclusion is FlowTree) ||
            original.isFlow && record.conclusion !is FlowTree) return false
        val templates = normalizedOriginalTemplates(original, flow = original.isFlow)
        val prepared = plan(parent, saved.enclosingExit, original, templates) ?: return false
        if (!prepared.emptyForBase(record.conclusion.base)) return false
        queryCounts.emptyReplays++
        return true
    }

    private fun observe(parent: Entry, loop: MethodBlock, link: LocalLink, exit: PortId,
                        original: PremiseKey, value: Facts): LoopObservation<LoopEnclosingResult> {
        val observer = observers.getOrPut(parent.scope to loop.id) {
        val adjacentId = checkNotNull(if (forward) layout[parent.scope.block].after else layout[parent.scope.block].before)
        val adjacent = layout[adjacentId]
        val adjacentScopes = routesByPort.values.asSequence().filter { route ->
            layout.contains(loop.id, route.from) &&
                (layout.contains(adjacentId, route.to) || isEmptyBlock(adjacent.id) &&
                    (!layout.contains(parent.scope.block, route.to) || route.feedbackLoop == parent.scope.block))
        }.map { BlockScope(adjacentId, inputPort(it.port, parent.scope.block, adjacentId)) }.toSet()
        val repeatScopes = loop.repeatPorts.map { BlockScope(loop.id, it) }.toSet()
        val adjacentDemands = adjacentScopes.associateWith { checkNotNull(config.demand).scope(key, it) }
        val repeatDemands = repeatScopes.associateWith { checkNotNull(config.demand).scope(key, it) }
        fun initials(scope: BlockScope, demand: ScopeDemandView, actual: Facts): Set<AdmittedInitial> {
            if (!keepLocalConclusion(scope.block, scope.entry, actual, count = false)) return emptySet()
            quantumQueries?.let { return it.initials(demand, actual, config.admissionPolicy) }
            ap.cancellation.checkpoint(); queryCounts.c2Queries++; queryCounts.c2Native++
            return demand.initials(actual, config.admissionPolicy).also { queryCounts.c2Rows += it.size }
        }
        fun labelled(actual: Facts): Set<LoopLabelledAdmission> = buildSet {
            for ((scope, demand) in adjacentDemands) for (initial in initials(scope, demand, actual))
                add(LoopLabelledAdmission(scope, LoopAdmissionFamily.ADJACENT, initial))
            for ((scope, demand) in repeatDemands) for (initial in initials(scope, demand, actual))
                add(LoopLabelledAdmission(scope, LoopAdmissionFamily.REPEAT, initial))
        }
        val enclosingDemand = parent.demand
        val views = LoopConsumerViews(parent.scope, parent.rootEntry,
            { actual -> adjacentDemands.flatMap { (scope, demand) -> initials(scope, demand, actual) }.toSet() },
            { actual -> repeatDemands.flatMap { (scope, demand) -> initials(scope, demand, actual) }.toSet() },
            { actual -> adjacentScopes.asSequence().flatMap { scope -> savedRows(scope, actual) }
                .flatMap { selected -> enclosingPorts(checkNotNull(selected.record.exitIn(config.direction)), parent.scope.block)
                    .asSequence().map { LoopObservedRecord(selected.record, it, selected) } } },
            { pr, actual -> adjacentScopes.asSequence().flatMap { scope ->
                config.normalTargets.candidates(key, scope, pr, actual, mode).asSequence()
            }.map { (row, member) -> LoopObservedTarget(row, member, methodExit) } },
            { portId, pr, actual -> intersect(parent, portId, pr, actual) },
            { portId, pr -> if (parent.rootEntry) checkNotNull(config.demand).acceptsTarget(key, pr, config.admissionPolicy)
                else checkNotNull(enclosingDemand).acceptsTarget(portId, pr, config.admissionPolicy) },
            { pr, id -> config.normalTargets.contains(key, if (parent.rootEntry) null else parent.scope, pr, id) },
            port.shared.interpreter::isSummaryBase, ::labelled,
            { pr, actual -> if (parent.rootEntry) root.adjustObservedMethodExit(pr, actual) else actual },
            admissionBundle = { actual -> LoopAdmissionBundle(
                { adjacentDemands.flatMap { (scope, demand) -> initials(scope, demand, actual).map {
                    LoopLabelledAdmission(scope, LoopAdmissionFamily.ADJACENT, it) } } },
                { repeatDemands.flatMap { (scope, demand) -> initials(scope, demand, actual).map {
                    LoopLabelledAdmission(scope, LoopAdmissionFamily.REPEAT, it) } } }) },
            keepEnclosingData = { output, actual -> keepLocalConclusion(parent.scope.block, output, actual, count = false) },
            skipEmptyDataReplay = { pr, actual, saved -> skipEmptyDataReplay(parent, pr, actual, saved) },
            precisionCursors = { actual ->
                val packet = ap.factsOf(actual.fact, actual.exclusion, Layer.DEMAND)
                buildList {
                    for ((family, demands) in listOf(LoopAdmissionFamily.ADJACENT to adjacentDemands,
                                                     LoopAdmissionFamily.REPEAT to repeatDemands))
                        for ((scope, demand) in demands) {
                            if (!keepLocalConclusion(scope.block, scope.entry, packet, count = false)) continue
                            val cursors = (demand as? EntryPrecisionView)?.precisionCursors(actual, config.admissionPolicy)
                                ?: continue
                            for (cursor in cursors) add(LoopPrecisionCursor(scope, family, cursor))
                        }
                }
            })
        LoopConsumerObservation(ops, mode, views)
        }
        val observation = observer.observe(original, value)
        if (LoopPipelineTrace.enabled(config.index, key)) LoopPipelineTrace.record(config.index, key, "loop-observation") {
            catalog(ap); text("parent", parent.scope.toString()); number("loop", loop.id.ordinal)
            number("exit", exit.ordinal); premise("P", original); facts("F", value)
            number("adjacentCount", observation.adjacentInitials.size)
            number("repeatCount", observation.repeatInitials.size)
            number("labelCount", observation.labelledAdmissions.size)
            number("enclosingCount", observation.enclosingResults.size)
            for ((index, admitted) in observation.adjacentInitials.withIndex()) {
                premise("adjacent${index}Initial", admitted.initial); text("adjacent${index}Layer", admitted.layer.name)
            }
            for ((index, admitted) in observation.repeatInitials.withIndex()) {
                premise("repeat${index}Initial", admitted.initial); text("repeat${index}Layer", admitted.layer.name)
            }
            for ((index, labelled) in observation.labelledAdmissions.withIndex()) {
                text("label${index}Scope", labelled.scope.toString()); text("label${index}Family", labelled.family.name)
                premise("label${index}Initial", labelled.admitted.initial); text("label${index}Layer", labelled.admitted.layer.name)
            }
            for ((index, result) in observation.enclosingResults.withIndex()) when (result) {
                is LoopEnclosingResult.Data -> {
                    text("result${index}Scope", result.scope.toString()); number("result${index}Exit", result.exit.ordinal)
                    premise("result${index}P", result.original); pattern("result${index}F", result.member.pattern)
                    text("result${index}Layer", result.member.layer.name); flag("result${index}Protected", result.member.nonSubsumable)
                }
                is LoopEnclosingResult.Terminal -> {
                    text("result${index}Scope", result.scope.toString()); number("result${index}Exit", result.exit.ordinal)
                    premise("result${index}P", result.original); text("result${index}Target", result.target.toString())
                }
            }
        }
        return observation
    }

    /** Barrier-only scalar census. It retains no edge, premise or form snapshot. */
    fun diagnosticStatistics(): String {
        val counts = restriction.statistics
        val gapDetails = if (layout.normalExitGaps.isEmpty()) "" else " normalGapDetails=" +
            layout.normalExitGaps.joinToString("|") {
                "${it.loop.ordinal}:headers[${it.headers.joinToString(",")}]:continuations[${it.continuations.joinToString(",")}]"
            }
        return "layoutBlocks=${layout.blocks.size} loops=${layout.blocks.count { it.isLoop }} " +
            "normalExitGaps=${layout.normalExitGaps.size} " +
            "maxDepth=${layout.blocks.maxOfOrNull { it.depth } ?: 0} entryScopes=${entries.size} " +
            "instantiatedStates=${entries.values.count { it.stateOrNull != null }} " +
            "liveInputGroups=${entries.values.sumOf { it.links.inputGroups.toLong() }} " +
            "completionPoints=${entries.values.sumOf { it.completions.size.toLong() }} " +
            "boundaryLimitOffers=$boundaryLimitOffers boundaryLimitCuts=$boundaryLimitCuts " +
            "localBoundaryOffers=$localBoundaryOffers localBoundaryDrops=$localBoundaryDrops " +
            "prePublicationLocalOffers=$prePublicationLocalOffers prePublicationDeadLocals=$prePublicationDeadLocals " +
            "localMasks=${liveLocals?.retainedMasks ?: 0} localMaskWords=${liveLocals?.retainedWords ?: 0} " +
            "c2Queries=${queryCounts.c2Queries} c2Hits=${queryCounts.c2Hits} c2Native=${queryCounts.c2Native} c2Rows=${queryCounts.c2Rows} " +
            "c5Plans=${queryCounts.plans} c5PlanChecks=${queryCounts.planChecks} c5PlanHits=${queryCounts.planHits} c5PlanFallbacks=${queryCounts.planFallbacks} " +
            "oversizedPlanRequests=${queryCounts.oversizedPlanRequests} c5PreparedQueries=${queryCounts.c5PreparedQueries} " +
            "c5NativeQueries=${queryCounts.c5NativeQueries} c5ReferenceFallbacks=${queryCounts.c5ReferenceFallbacks} " +
            "emptyDataReplays=${queryCounts.emptyReplays} " +
            "offers=${counts.offers} bypasses=${counts.bypasses} scalars=${counts.scalarQueries} " +
            "observations=${counts.observations} trials=${counts.trials} drops=${counts.drops} " +
            "cuts=${counts.cuts} rawFallbacks=${counts.rawFallbacks} " +
            "certificates=${counts.certificates} certificateFallbacks=${counts.certificateFallbacks} budgetsSkipped=${counts.budgetsSkipped} " +
            (localMatchCounts?.diagnosticStatistics()?.plus(" ") ?: "") +
            (savedSelectionCounts?.diagnosticStatistics()?.plus(" ") ?: "") +
            "preparedExitEntries=${preparedExits.preparations} preparedExitTargetMasks=${preparedExits.targetMaskBuilds}" + gapDetails
    }

    /** Numeric-only snapshots at the owner barrier; no completion facts escape. */
    fun completionScalarStatistics(): Sequence<ScalarIdentityStatistics> = sequence {
        for (entry in entries.values) for (store in entry.completions.values) {
            store.scalarStatisticsSnapshot()?.let { yield(it) }
        }
    }

    fun forEachLocalInput(scope: BlockScope, visit: (LocalLink, Facts) -> Unit) {
        entries[scope]?.links?.forEachInput(visit)
    }
    /** Transfer every existing input directory, including saved-only entries. */
    fun detachJoinedLocalInputs(): Map<BlockScope, JoinedLocalInputs> {
        requireIdle()
        val acquired = LinkedHashMap<BlockScope, JoinedLocalInputs>()
        try {
            for ((scope, entry) in entries) {
                val moved = entry.links.detachJoinedInputs()
                try { acquired[scope] = moved } catch (error: Throwable) {
                    try { moved.close() } catch (cleanup: Throwable) { if (cleanup !== error) error.addSuppressed(cleanup) }
                    throw error
                }
            }
            return acquired
        } catch (error: Throwable) {
            for (moved in acquired.values) try { moved.close() } catch (cleanup: Throwable) {
                if (cleanup !== error) error.addSuppressed(cleanup)
            }
            throw error
        }
    }
    fun scopedSummaries(): Sequence<ScopedRunSummary> = sequence {
        for ((scope, e) in entries) if (scope != BlockScope.ROOT && e.stateOrNull != null)
            for ((exit, rows) in e.state.portSummaries.entries())
                yield(ScopedRunSummary(ScopedSummaryKey(key, scope, exit), rows))
    }
    fun scopedTargets(): Sequence<ScopedTargetRows> = entries.asSequence().filter { it.key != BlockScope.ROOT && it.value.stateOrNull != null }
        .map { (scope, e) -> ScopedTargetRows(key, scope, e.state.targets, methodExit) }
    fun scopedOutgoingTargets(): Sequence<ScopedTargetRows> = sequence {
        for ((scope, e) in entries) if (scope != BlockScope.ROOT && e.stateOrNull != null) {
            val byAddress = e.state.outgoingTargets.groupBy { row ->
                targetHandoffScope(scope, config.direction, e.borrowedExceptionalNormalZero, row)
            }
            for ((address, rows) in byAddress) yield(ScopedTargetRows(key, address, rows, methodExit))
        }
    }
    fun freezeChildren() {
        requireIdle()
        var failure: Throwable? = null
        fun release(action: () -> Unit) {
            try { action() } catch (error: Throwable) {
                val prior = failure
                if (prior == null) failure = error else if (prior !== error) prior.addSuppressed(error)
            }
        }
        try {
            for ((scope, e) in entries) if (scope != BlockScope.ROOT) e.stateOrNull?.let { state -> release { state.freeze() } }
            for (e in entries.values) release { e.links.clear() }
        } finally {
            entries.clear(); ready.clear(); pending.clear(); observers.clear(); preparedExits.clear(); released = true
        }
        failure?.let { throw it }
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.BlockScope
import org.opentaint.dataflow.bidi.store.Record
import org.opentaint.dataflow.graph.PortId

/** The router identifies the enclosing region's exit, preserving the saved row's actual port. */
internal class LoopObservedRecord(val record: Record, val enclosingExit: PortId,
                                  private val selection: SavedRecordSelection? = null) {
    fun forEachReversedAt(actual: Facts, ops: ApOps, emit: (RecordLeafView, Boolean) -> Unit) =
        (selection ?: SavedRecordSelection(record)).forEachReversedAt(actual, ops, emit)

    // Selected positions are an invocation annotation. Preserve the existing observation key.
    override fun equals(other: Any?): Boolean = other is LoopObservedRecord &&
        record == other.record && enclosingExit == other.enclosingExit
    override fun hashCode(): Int = 31 * record.hashCode() + enclosingExit.hashCode()
}
internal data class LoopObservedTarget(val row: TargetSummary, val member: Int, val enclosingExit: PortId)

/** Scope, complete original and exit are part of the observation, not only AP geometry. */
internal sealed interface LoopEnclosingResult {
    data class Data(val scope: BlockScope, val exit: PortId, val original: PremiseKey,
                    val member: LoopObservedMember) : LoopEnclosingResult
    data class Terminal(val scope: BlockScope, val exit: PortId, val original: PremiseKey,
                        val target: Target) : LoopEnclosingResult
}

/** Frozen-snapshot adapters. They perform lookups only and never publish their query results. */
internal class LoopConsumerViews(
    val enclosingScope: BlockScope,
    val enclosingIsRoot: Boolean,
    val adjacentInitials: (Facts) -> Set<AdmittedInitial>,
    val repeatInitials: (Facts) -> Set<AdmittedInitial>,
    val savedRecords: (Facts) -> Sequence<LoopObservedRecord>,
    val savedTargets: (PremiseKey, Facts) -> Sequence<LoopObservedTarget>,
    val intersectEnclosing: (PortId, PremiseKey, Facts) -> List<Facts>,
    val acceptsEnclosingTarget: (PortId, PremiseKey) -> Boolean,
    val hasSavedEnclosingTarget: (PremiseKey, ReportId) -> Boolean,
    val isPublicSummaryBase: (AccessPathBase) -> Boolean,
    val labelledAdmissions: (Facts) -> Collection<LoopLabelledAdmission> = { emptyList() },
    val adjustEnclosingData: (PremiseKey, Facts) -> Facts? = { _, value -> value },
    val admissionBundle: ((Facts) -> LoopAdmissionBundle)? = null,
    val keepEnclosingData: (PortId, Facts) -> Boolean = { _, _ -> true },
    val skipEmptyDataReplay: (PremiseKey, Facts, LoopObservedRecord) -> Boolean = { _, _, _ -> false },
    val precisionCursors: (Pattern) -> List<LoopPrecisionCursor>? = { null },
)

/** Complete three-family observer. All scratch is local to one query invocation. */
internal class LoopConsumerObservation(
    private val ops: ApOps,
    private val mode: ApMode,
    private val views: LoopConsumerViews,
) {
    private val application = LocalRelationApplication(ops, mode)

    fun precisionCursors(actual: Pattern): List<LoopPrecisionCursor>? = views.precisionCursors(actual)

    fun observe(original: PremiseKey, value: Facts): LoopObservation<LoopEnclosingResult> {
        val ap = ops.manager
        ap.cancellation.checkpoint()
        val bundle = views.admissionBundle?.invoke(value)
        val adjacent = bundle?.adjacent() ?: views.adjacentInitials(value)
        val full = EnclosingResults(ops)
        fun sink(exit: PortId): LocalRelationOut = object : LocalRelationOut {
            override fun data(original: PremiseKey, value: Facts) {
                ap.cancellation.checkpoint()
                val adjusted = views.adjustEnclosingData(original, value) ?: return
                if (!views.keepEnclosingData(exit, adjusted)) return
                if (views.enclosingIsRoot && !views.isPublicSummaryBase(adjusted.base)) return
                val normalized = normalizeFlowSummary(ap, original, adjusted)
                for (kept in views.intersectEnclosing(exit, normalized.premise, normalized.facts))
                    full.addData(views.enclosingScope, exit, normalized.premise, kept)
            }

            override fun target(original: PremiseKey, target: Target) {
                ap.cancellation.checkpoint()
                val accepted = when (target) {
                    Target.DemandTarget -> views.acceptsEnclosingTarget(exit, original)
                    is Target.NormalTarget -> mode.direction == Direction.FORWARD &&
                        !views.hasSavedEnclosingTarget(original, target.id)
                }
                if (accepted) full.addTarget(views.enclosingScope, exit, original, target)
            }

            // The observation is a pure query. Actual saved replay delivers its ordinary requests.
            override fun markRequest(mark: TaintMark) = Unit
        }

        val seen = LinkedHashSet<LoopObservedRecord>()
        for (saved in views.savedRecords(value)) {
            ap.cancellation.checkpoint()
            if (!seen.add(saved)) continue
            if (views.skipEmptyDataReplay(original, value, saved)) continue
            val record = saved.record
            val output = sink(saved.enclosingExit)
            if (record.direction == mode.direction) application.applyRecord(value, original, record, output)
            else {
                saved.forEachReversedAt(value, ops) { view, protected ->
                    application.applyRecordView(value, original, view, protected, output)
                }
            }
        }
        for (saved in views.savedTargets(original, value)) {
            ap.cancellation.checkpoint()
            // A saved ZERO -> NormalTarget has no new effect. Other ND rows use a metadata
            // arm view here only; executable local replay still joins their complete binding.
            if (saved.row.premise.isZero && saved.row.target is Target.NormalTarget) continue
            val initial = saved.row.premise.member(saved.member)
            val layer = application.targetArmLayer(value, initial, saved.row.target, saved = true) ?: continue
            if (saved.row.target is Target.NormalTarget && layer != Layer.NORMAL) continue
            sink(saved.enclosingExit).target(original, saved.row.target)
        }
        val repeat = bundle?.repeat() ?: views.repeatInitials(value)
        return LoopObservation(adjacent, full.freeze(), repeat, bundle?.labelled() ?: views.labelledAdmissions(value))
    }
}

/** Union protection before freezing the complete result signature. */
private class EnclosingResults(private val ops: ApOps) {
    private data class Header(val scope: BlockScope, val exit: PortId, val original: PremiseKey)
    private val data = LinkedHashMap<Header, LoopObservedFacts>()
    private val targets = LinkedHashSet<LoopEnclosingResult.Terminal>()

    fun addData(scope: BlockScope, exit: PortId, original: PremiseKey, value: Facts) {
        data.getOrPut(Header(scope, exit, original)) { LoopObservedFacts(ops) }.add(value)
    }

    fun addTarget(scope: BlockScope, exit: PortId, original: PremiseKey, target: Target) {
        targets += LoopEnclosingResult.Terminal(scope, exit, original, target)
    }

    fun freeze(): Set<LoopEnclosingResult> = buildSet {
        for ((header, values) in data) for (member in values.freeze()) {
            ops.manager.cancellation.checkpoint()
            add(LoopEnclosingResult.Data(header.scope, header.exit, header.original, member))
        }
        addAll(targets)
    }
}

package org.opentaint.dataflow.bidi.engine

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.store.ExactDemandResults
import org.opentaint.dataflow.bidi.store.BlockScope
import java.util.Collections

/** A frozen query result. R contains the complete scoped/port-labelled enclosing result key.
 *
 * The observer must include all three families. A successful first family is not permission to
 * stop the query. It must not execute rules, subscriptions, source hooks or static effects.
 */
internal class LoopObservation<R>(
    adjacentInitials: Collection<AdmittedInitial>,
    enclosingResults: Collection<R>,
    repeatInitials: Collection<AdmittedInitial>,
    labelledAdmissions: Collection<LoopLabelledAdmission> = emptyList(),
) {
    val adjacentInitials: Set<AdmittedInitial> = frozenSet(adjacentInitials)
    val enclosingResults: Set<R> = frozenSet(enclosingResults)
    val repeatInitials: Set<AdmittedInitial> = frozenSet(repeatInitials)
    val labelledAdmissions: Set<LoopLabelledAdmission> = frozenSet(labelledAdmissions)
    val isEmpty: Boolean get() = adjacentInitials.isEmpty() && enclosingResults.isEmpty() && repeatInitials.isEmpty() &&
        labelledAdmissions.isEmpty()

    override fun equals(other: Any?): Boolean = this === other || other is LoopObservation<*> &&
        adjacentInitials == other.adjacentInitials && enclosingResults == other.enclosingResults &&
        repeatInitials == other.repeatInitials && labelledAdmissions == other.labelledAdmissions

    override fun hashCode(): Int = ((adjacentInitials.hashCode() * 31 + enclosingResults.hashCode()) * 31 +
        repeatInitials.hashCode()) * 31 + labelledAdmissions.hashCode()
}

internal enum class LoopAdmissionFamily { ADJACENT, REPEAT }
internal data class LoopLabelledAdmission(val scope: BlockScope, val family: LoopAdmissionFamily,
                                         val admitted: AdmittedInitial)

private fun <T> frozenSet(values: Collection<T>): Set<T> =
    Collections.unmodifiableSet(LinkedHashSet(values))

/** Exact geometry and annotation. Facts.equals intentionally omits the protection annotation. */
internal data class LoopObservedMember(val pattern: Pattern, val layer: Layer, val nonSubsumable: Boolean)

/** Query-local exact union. A protected copy wins over an otherwise identical plain copy. */
internal class LoopObservedFacts(private val ops: ApOps) {
    private data class Key(val pattern: Pattern, val layer: Layer)
    private val members = LinkedHashMap<Key, Boolean>()

    fun add(facts: Facts) {
        for (scalar in annotatedLoopScalars(ops, facts)) {
            ops.manager.cancellation.checkpoint()
            val pattern = ops.leaves(scalar).single()
            val key = Key(pattern, scalar.layer)
            members[key] = members[key] == true || scalar is TaintTree && scalar.nonSubsumable != null
        }
    }

    fun freeze(): Set<LoopObservedMember> = frozenSet(members.map { (key, protected) ->
        LoopObservedMember(key.pattern, key.layer, protected)
    })
}

/** Scalar output memberships with each exact protection coordinate retained before observing it. */
internal fun annotatedLoopScalars(ops: ApOps, packet: Facts): Sequence<Facts> = sequence {
    val ap = ops.manager
    if (packet is Reach) {
        ap.cancellation.checkpoint()
        yield(packet)
        return@sequence
    }
    for (leaf in ops.leaves(packet)) {
        ap.cancellation.checkpoint()
        val plain = ap.factsOf(leaf.fact, leaf.exclusion, packet.layer)
        yield(if (packet is TaintTree && plain is TaintTree)
            plain.withProtection(packet.nonSubsumable, ap.cancellation) else plain)
    }
}

/** Counts stored summary geometry, before a caller suffix is applied. ZERO has depth zero. */
internal fun loopFieldLength(premise: InitialAp): Int =
    if (premise.isZero) 0 else premise.path?.counted ?: 0

internal fun loopFieldLength(conclusion: Pattern): Int =
    conclusion.fact.path.count { it.isCounted() }

/** ND arms are restriction metadata only. The complete execution must have finished already. */
internal fun loopSummaryGrows(premise: PremiseKey, scalarConclusion: Pattern): Boolean {
    val outputDepth = loopFieldLength(scalarConclusion)
    premise.forEachMember { if (outputDepth <= loopFieldLength(it)) return false }
    return true
}

internal class LoopRestrictionStatistics {
    var offers: Long = 0; internal set
    var bypasses: Long = 0; internal set
    var scalarQueries: Long = 0; internal set
    var observations: Long = 0; internal set
    var trials: Long = 0; internal set
    var drops: Long = 0; internal set
    var cuts: Long = 0; internal set
    var rawFallbacks: Long = 0; internal set
    var certificates: Long = 0; internal set
    var certificateFallbacks: Long = 0; internal set
    var budgetsSkipped: Long = 0; internal set
}

/** Conservative shortest-safe-prefix reference from the selected loop specification.
 *
 * A call is for one stored output geometry, not an arbitrary packed summary. Applied values may
 * still contain several suffix/mark memberships; observe and cut those independently. The caller
 * captures the complete enclosing original, actual output port and immutable scope views in
 * [observe]. Restriction neither rewrites that context nor publishes a result.
 */
internal class LoopOutputRestriction(private val ops: ApOps) {
    val statistics = LoopRestrictionStatistics()

    fun <R> restrict(
        run1: Boolean,
        rowPremise: PremiseKey,
        scalarConclusion: Pattern,
        appliedValue: Facts,
        observe: (Facts) -> LoopObservation<R>,
    ): List<Facts> = restrict(run1, loopSummaryGrows(rowPremise, scalarConclusion), appliedValue, observe)

    /** Native reverse views keep a transient Pattern premise; classify that stored geometry
     * directly rather than interning a query-only MUST initial merely to call the gate. */
    fun <R> restrict(
        run1: Boolean,
        grows: Boolean,
        appliedValue: Facts,
        observe: (Facts) -> LoopObservation<R>,
    ): List<Facts> = restrictWithCertificate(run1, grows, appliedValue, observe, null)

    fun <R> restrict(run1: Boolean, grows: Boolean, appliedValue: Facts,
                     session: LoopRestrictionSession<R>): List<Facts> =
        restrictWithCertificate(run1, grows, appliedValue, session.observe, session::certifiedFirstBudget)

    private fun <R> restrictWithCertificate(run1: Boolean, grows: Boolean, appliedValue: Facts,
                                           observe: (Facts) -> LoopObservation<R>,
                                           firstBudget: ((Facts, LoopObservation<R>) -> Int?)?): List<Facts> {
        val ap = ops.manager
        ap.cancellation.checkpoint()
        statistics.offers++
        if (run1 || appliedValue is Reach || !grows) {
            statistics.bypasses++
            return listOf(appliedValue)
        }
        val result = ExactDemandResults(ap)
        for (scalar in annotatedLoopScalars(ops, appliedValue)) {
            restrictScalar(scalar, observe, firstBudget)?.let(result::add)
        }
        return result.all()
    }

    private fun <R> restrictScalar(raw: Facts, observe: (Facts) -> LoopObservation<R>,
                                  firstBudget: ((Facts, LoopObservation<R>) -> Int?)?): Facts? {
        ops.manager.cancellation.checkpoint()
        statistics.scalarQueries++
        statistics.observations++
        val baseline = observe(raw)
        if (baseline.isEmpty) {
            statistics.drops++
            return null
        }
        val depth = when (raw) {
            is Reach -> 0
            is FlowTree -> raw.root.boundedDepth
            is TaintTree -> raw.root.boundedDepth
        }
        val certified = if (depth > 1) firstBudget?.invoke(raw, baseline) else null
        if (certified != null) {
            check(certified in 2..depth)
            statistics.certificates++
            statistics.budgetsSkipped += certified - 1
        } else if (firstBudget != null && depth > 1) statistics.certificateFallbacks++
        for (budget in (certified ?: 1) until depth) {
            ops.manager.cancellation.checkpoint()
            statistics.trials++
            var candidate: Facts? = null
            ops.limit(raw, budget, object : ApOut {
                override fun result(f: Facts) {
                    check(candidate == null) { "A scalar proper-prefix limit must have one output" }
                    candidate = f
                }

                override fun markRequest(mark: TaintMark) = error("A loop prefix cut cannot request a mark")
            })
            val cut = checkNotNull(candidate) { "A scalar field limit must have an output" }
            statistics.observations++
            if (observe(cut) == baseline) {
                check(cut.layer == Layer.DEMAND) { "A proper loop prefix cut must be DEMAND" }
                statistics.cuts++
                return cut
            }
        }
        statistics.rawFallbacks++
        return raw
    }
}

package org.opentaint.dataflow.bidi.driver

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.engine.RunConfig
import org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer
import org.opentaint.dataflow.bidi.engine.RunResult
import org.opentaint.dataflow.bidi.engine.RunStatus
import org.opentaint.dataflow.bidi.engine.SharedObjects
import org.opentaint.dataflow.bidi.interp.SinkRule
import org.opentaint.dataflow.bidi.store.DemandStore
import org.opentaint.dataflow.bidi.store.FrozenStaticCompletion
import org.opentaint.dataflow.bidi.store.guidancePattern
import org.opentaint.dataflow.bidi.store.DemandEntry
import org.opentaint.dataflow.bidi.store.DemandExit
import org.opentaint.dataflow.bidi.store.PairedDemand
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.Collections
import mu.KotlinLogging
import kotlin.time.TimeSource

/** Immutable outgoing demand, seeds and accepted explicit-pattern counts.
 * [of] counts only successful normalized builder insertions. Its method-key support is
 * empty exactly when the built explicit snapshot is empty; virtual static families are separate.
 * Manually constructed test values need not have that binding.
 */
class HandOff(val demand: DemandStore, val seeds: SeedIndex, demandEdges: Map<MethodKey, Int>) {
    val demandEdges: Map<MethodKey, Int> = Collections.unmodifiableMap(LinkedHashMap(demandEdges))

    companion object {
        private val logger = KotlinLogging.logger {}
        fun of(config: RunConfig, result: RunResult<RunMethodAnalyzer>, shared: SharedObjects): HandOff {
            check(result.status == RunStatus.COMPLETE) { "A hand-off needs a complete run" }
            shared.cancellation.checkpoint()
            val counts = LinkedHashMap<MethodKey, Int>()
            val (demand, seeds) = if (config.direction == Direction.FORWARD)
                toBackward(result, shared, counts, config.run1) else toForward(result, shared, counts)
            return HandOff(demand, seeds, counts)
        }

        private inline fun forEachDemandPiece(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                                             direction: Direction,
                                             body: (MethodKey, PremiseKey, Pattern) -> Unit) {
            for (actor in result.analyzers) {
                shared.cancellation.checkpoint()
                for ((premise, facts) in actor.summaries.demandEdges(direction)) {
                    shared.cancellation.checkpoint()
                    if (!actor.mode.run1 && facts is FlowTree && facts.layer == Layer.DEMAND)
                        check(facts.tail == Tail.ANY && facts.exclusion == ExclusionSet.Empty) {
                            "A restricted FLOW demand result must be ANY with empty field exclusions"
                        }
                    for (leaf in shared.ops.leaves(facts)) {
                        shared.cancellation.checkpoint()
                        body(actor.key, premise, leaf)
                    }
                }
            }
        }

        private fun toBackward(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                               counts: MutableMap<MethodKey, Int>, run1: Boolean): Pair<DemandStore, SeedIndex> {
            val demand = DemandStore.Builder(shared.ap)
            val completionStart = TimeSource.Monotonic.markNow()
            val joinedCompletion = if (run1) result.staticCompletion else null
            val completion = if (run1 && joinedCompletion == null)
                FrozenStaticCompletion.Builder(shared.ap, shared.staticCallGraph) else null
            if (run1) demand.withSharedStaticCarry()
            if (joinedCompletion != null) {
                demand.withCompletion(joinedCompletion)
                for ((owner, view) in joinedCompletion.scopedViews())
                    demand.withCompletion(owner.method, owner.local, view)
                logger.info { "BIDI_STATIC_CLOSURE_HANDOFF run=1 source=JOINED ${joinedCompletion.statistics()}" }
            }
            // Synthetic frozen RunResults in small tests have no runner-owned
            // pre-release phase. Their fallback uses local seeds only; real
            // RunManager results supply the joined completion above.
            if (completion != null) {
                for (actor in result.analyzers) {
                    for (edge in actor.staticGuidanceSeeds.frozenRows()) {
                        shared.cancellation.checkpoint()
                        completion.addSeed(actor.key, edge)
                    }
                    for (key in actor.freezeStaticWriteCandidates().lostRows()) {
                        shared.cancellation.checkpoint()
                        completion.addSeed(actor.key, key.original.toPattern(), key.result)
                    }
                    for (terminal in actor.outgoingTargets) {
                        shared.cancellation.checkpoint()
                        check(terminal.target == org.opentaint.dataflow.bidi.engine.Target.DemandTarget)
                        val original = checkNotNull(terminal.premise as? InitialAp) { "Run-1 cannot retain an ND original" }
                        completion.addTarget(actor.key, original.toPattern())
                    }
                }
            }
            val seedCaptureTime = completionStart.elapsedNow()
            val projectionStart = TimeSource.Monotonic.markNow()
            forEachDemandPiece(result, shared, Direction.FORWARD) { method, premise, piece ->
                val entry = guidancePattern(piece)
                premise.forEachMember { member ->
                    shared.cancellation.checkpoint()
                    val from = guidancePattern(member.toPattern())
                    completion?.addBoundary(method, from, entry)
                    val pattern = DemandPattern(entry, from)
                    if (demand.add(method, pattern)) counts.merge(method, 1, Int::plus)
                }
            }
            projectTargets(result, shared, demand, counts)
            projectBlocks(result, shared, Direction.FORWARD, run1, demand, counts, completion)
            if (completion != null) {
                val projectionTime = projectionStart.elapsedNow()
                val indexStart = TimeSource.Monotonic.markNow()
                val frozen = completion.build()
                demand.withCompletion(frozen)
                for ((owner, view) in frozen.scopedViews()) demand.withCompletion(owner.method, owner.local, view)
                logger.info { "BIDI_STATIC_CLOSURE_FREEZE run=1 source=LOCAL_FROZEN_INPUT freezeTime=${completionStart.elapsedNow()} seedTime=$seedCaptureTime projectionTime=$projectionTime indexTime=${indexStart.elapsedNow()} ${frozen.statistics()}" }
            }
            val seeds = result.analyzers.flatMap { it.sinkSeeds }
            return demand.build() to SeedIndex.of(seeds)
        }

        private fun projectTargets(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                                   demand: DemandStore.Builder, counts: MutableMap<MethodKey, Int>) {
            for (actor in result.analyzers) for (row in actor.outgoingTargets) {
                shared.cancellation.checkpoint()
                for (member in row.premise.members) {
                    val exit = if (member.isZero) DemandExit.Zero
                        else DemandExit.Data(guidancePattern(member.toPattern()))
                    if (demand.add(actor.key, PairedDemand(DemandEntry.Target, exit)))
                        counts.merge(actor.key, 1, Int::plus)
                }
            }
        }

        private fun projectBlocks(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                                  direction: Direction, run1: Boolean,
                                  demand: DemandStore.Builder, counts: MutableMap<MethodKey, Int>,
                                  completion: FrozenStaticCompletion.Builder? = null) {
            projectBlockHandOff(shared.ap, direction, run1,
                result.analyzers.asSequence().flatMap { it.blockSummaries() },
                result.analyzers.asSequence().flatMap { it.blockOutgoingTargets() }, demand, counts,
                onBoundary = { key, from, to -> completion?.addScopedSeed(key, from, to) })
            if (run1 && completion != null) for (actor in result.analyzers)
                for (terminal in actor.blockOutgoingTargets()) for (row in terminal.rows) {
                    val original = checkNotNull(row.premise as? InitialAp) { "Run-1 cannot retain an ND original" }
                    completion.addScopedTarget(org.opentaint.dataflow.bidi.store.ScopedSummaryKey(
                        terminal.method, terminal.scope, terminal.exit), original.toPattern())
                }
        }

        private fun toForward(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                              counts: MutableMap<MethodKey, Int>): Pair<DemandStore, SeedIndex> {
            val demand = DemandStore.Builder(shared.ap)
            forEachDemandPiece(result, shared, Direction.BACKWARD) { method, premise, piece ->
                val pattern = when (premise) {
                    is InitialAp -> DemandPattern(guidancePattern(piece),
                        guidancePattern(premise.toPattern()))
                    is PremiseSet -> error("The backward run has no multi-premise summary (ap.md §9.2)")
                }
                if (demand.add(method, pattern)) counts.merge(method, 1, Int::plus)
            }
            projectTargets(result, shared, demand, counts)
            projectBlocks(result, shared, Direction.BACKWARD, false, demand, counts)
            val seeds = ArrayList<Seed>()
            for (actor in result.analyzers) {
                shared.cancellation.checkpoint()
                for ((method, statement, edge, action) in checkNotNull(actor.sourceHits).occurrences()) {
                    shared.cancellation.checkpoint()
                    seeds += Seed.Source(method, statement, edge, action)
                }
            }
            return demand.build() to SeedIndex.of(seeds)
        }
    }
}

/** Use the same predicate handle and literal seeds as the previous handoff. */
internal fun sinkSeedsFor(sink: SinkRule, method: MethodKey, at: CommonInst): List<Seed> = when {
    sink.predicate != null && !sink.unconditional ->
        listOf(Seed.PredicateSink(checkNotNull(sink.occurrenceId), method, at))
    sink.predicate != null -> emptyList()
    else -> sink.seedPatterns().map { Seed.Sink(sink.rule, method, at, it) }
}

/** GROUP evaluation must retain the original FULL seed patterns, as before.
 * Read the existing full form; do not keep a second seed or rule cache. */
internal fun fullSinkSeedsFor(shared: SharedObjects, sink: SinkRule,
                              method: MethodKey, at: CommonInst): List<Seed> {
    val seeds = LinkedHashSet<Seed>()
    withSinksAt(shared, method, at) { sinks ->
        for (full in sinks) {
            shared.cancellation.checkpoint()
            if (full.rule == sink.rule) seeds += sinkSeedsFor(full, method, at)
        }
    }
    return seeds.toList()
}

/** Existing full-form lookup used by sink handoff before terminal reporting. */
private fun withSinksAt(shared: SharedObjects, key: MethodKey, statement: CommonInst,
                       use: (List<SinkRule>) -> Unit) {
    val forms = shared.contexts.forms(key)
    val call = shared.language.getCallExpr(statement)
    if (call != null) forms.withCall(Direction.FORWARD, statement, call) { use(it.sinks) }
    else if (shared.interpreter.exitNodes(key).any {
        shared.cancellation.checkpoint(); it.node == statement
    }) forms.withExitRules(Direction.FORWARD, statement) { use(it.rules.sinks) }
}

package org.opentaint.dataflow.bidi.driver

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.engine.Target
import org.opentaint.dataflow.bidi.engine.TargetSummary
import org.opentaint.dataflow.bidi.store.*
import org.opentaint.dataflow.graph.PortId

/** Only entered scopes contribute rows. A terminal uses its logical exit port.
 * Runtime routing must resolve ROOT_EXIT through the existing directed backend
 * boundary/discovery graph. It is not permission to seed all physical ports. */
data class ScopedTargetRows(
    val method: MethodKey,
    val scope: BlockScope,
    val rows: Collection<TargetSummary>,
    val exit: PortId = PortId.ROOT_EXIT,
)

/** The same AP handoff as the public method boundary, with both control ports
 * reversed. One successful normalized insertion counts as one outgoing row. */
fun projectBlockHandOff(
    ap: ApManager,
    direction: Direction,
    run1: Boolean,
    summaries: Sequence<ScopedRunSummary>,
    targets: Sequence<ScopedTargetRows>,
    demand: DemandStore.Builder,
    counts: MutableMap<MethodKey, Int>,
    onBoundary: (ScopedSummaryKey, Pattern, Pattern) -> Unit = { _, _, _ -> },
) {
    val ops = ApOps(ap)
    for ((producer, store) in summaries) {
        ap.cancellation.checkpoint()
        val next = producer.reversed()
        for ((premise, facts) in store.demandEdges(direction)) {
            ap.cancellation.checkpoint()
            if (!run1 && facts is FlowTree && facts.layer == Layer.DEMAND)
                check(facts.tail == Tail.ANY && facts.exclusion == ExclusionSet.Empty) {
                    "A restricted block FLOW demand result must be ANY with empty field exclusions"
                }
            if (direction == Direction.BACKWARD)
                check(premise is InitialAp) { "The backward run has no multi-premise summary (ap.md §9.2)" }
            for (leaf in ops.leaves(facts)) {
                ap.cancellation.checkpoint()
                val entry = guidancePattern(leaf)
                premise.forEachMember { member ->
                    ap.cancellation.checkpoint()
                    val exit = guidancePattern(member.toPattern())
                    onBoundary(producer, exit, entry)
                    if (demand.add(next.method, next.scope, next.exit, DemandPattern(entry, exit)))
                        counts.merge(next.method, 1, Int::plus)
                }
            }
        }
    }
    for (terminal in targets) {
        ap.cancellation.checkpoint()
        val next = ScopedSummaryKey(terminal.method, terminal.scope, terminal.exit).reversed()
        for (row in terminal.rows) {
            ap.cancellation.checkpoint()
            check(row.target == Target.DemandTarget) { "Only outgoing DEMAND Targets guide a later run" }
            row.premise.forEachMember { member ->
                ap.cancellation.checkpoint()
                val exit = if (member.isZero) DemandExit.Zero
                    else DemandExit.Data(guidancePattern(member.toPattern()))
                if (demand.add(next.method, next.scope, next.exit, PairedDemand(DemandEntry.Target, exit)))
                    counts.merge(next.method, 1, Int::plus)
            }
        }
    }
}
